          display: flex;
          align-items: center;
          justify-content: center;
          font-size: 12px;
          padding: 0 8px;
          flex-shrink: 0;
        }
      `}
    >
      {/* <div className='inputrange-value'>
        <span>{local}</span>
      </div> */}
      <input
        type='range'
        min={min}
        max={max}
        step={step}
        value={local}
        onChange={handleChange}
        onPointerDown={() => setSliding(true)}
        onPointerUp={() => {
          setSliding(false)
