export function cls(...args) {
  let str = ''
  for (const arg of args) {
    if (typeof arg === 'string') {
      str += ' ' + arg
    } else if (typeof arg === 'object') {
      for (const key in arg) {
        const value = arg[key]
        if (value) str += ' ' + key
      }
    }
  }
  return str
}

import { useEffect, useLayoutEffect, useRef, useState } from 'react'

export function useElemSize() {
  const elemRef = useRef(null)
  const [width, setWidth] = useState(0)
  const [height, setHeight] = useState(0)
  useEffect(() => {
    const elem = elemRef.current
    if (!elem) return
    setWidth(elem.offsetWidth)
    setHeight(elem.offsetHeight)
    const observer = new ResizeObserver(entries => {
      setWidth(elem.offsetWidth)
      setHeight(elem.offsetHeight)
    })
    observer.observe(elem)
    return () => {
      observer.disconnect()
    }
  }, [])
  return [elemRef, width, height]
}

import { useEffect, useMemo, useState } from 'react'
import { isBoolean } from 'lodash-es'

export function useFullscreen(targetRef) {
  const [enabled, setEnabled] = useState(false)

  const supported = useMemo(() => {
    const docEl = document.documentElement
    return !!(
      docEl.requestFullscreen ||
      docEl.webkitRequestFullscreen ||
      docEl.mozRequestFullScreen ||
      docEl.msRequestFullscreen
    )
  }, [])

  const toggle = value => {
    const element = targetRef?.current || document.documentElement
    const shouldEnable = isBoolean(value) ? value : !enabled

    if (!supported) return

    if (shouldEnable) {
      const request =
        element.requestFullscreen ||
        element.webkitRequestFullscreen ||
        element.mozRequestFullScreen ||
        element.msRequestFullscreen

      request?.call(element)
    } else {
      const exit =
        document.exitFullscreen ||
        document.webkitExitFullscreen ||
        document.mozCancelFullScreen ||
        document.msExitFullscreen

      exit?.call(document)
    }
  }

  useEffect(() => {
    const handleChange = () => {
      const isFullscreen =
        document.fullscreenElement ||
        document.webkitFullscreenElement ||
        document.mozFullScreenElement ||
        document.msFullscreenElement

      setEnabled(!!isFullscreen)
    }

    document.addEventListener('fullscreenchange', handleChange)
    document.addEventListener('webkitfullscreenchange', handleChange)
    document.addEventListener('mozfullscreenchange', handleChange)
    document.addEventListener('MSFullscreenChange', handleChange)

    return () => {
      document.removeEventListener('fullscreenchange', handleChange)
      document.removeEventListener('webkitfullscreenchange', handleChange)
      document.removeEventListener('mozfullscreenchange', handleChange)
      document.removeEventListener('MSFullscreenChange', handleChange)
    }
  }, [])

  return [supported, enabled, toggle]
}

import { cloneDeep, debounce } from 'lodash-es'
import { useEffect } from 'react'
import { storage } from '../../core/storage'

const STORAGE_KEY = 'panes'

let info = storage.get(STORAGE_KEY)

if (!info || info.v !== 1) {
  info = {
    v: 1,
    count: 0,
    configs: {
      // [id]: { x, y, width, height }
    },
  }
}

const persist = debounce(() => storage.set(STORAGE_KEY, info), 300)

let layer = 0

export function usePane(id, paneRef, headRef, resizable = false) {
  useEffect(() => {
    let config = info.configs[id]
    const pane = paneRef.current

    if (!config) {
      const count = ++info.count
      config = {
        id,
        y: count * 20,
        x: count * 20,
        width: pane.offsetWidth,
        height: pane.offsetHeight,
        layer: 0,
      }
      info.configs[id] = config
      persist()
    }

    if (!resizable) {
      config.width = pane.offsetWidth
      config.height = pane.offsetHeight
    }

    layer++

    // ensure pane is within screen bounds so it can't get lost
    const maxX = window.innerWidth - config.width
    const maxY = window.innerHeight - config.height
    config.x = Math.min(Math.max(0, config.x), maxX)
    config.y = Math.min(Math.max(0, config.y), maxY)

    pane.style.top = `${config.y}px`
    pane.style.left = `${config.x}px`
    if (resizable) {
      pane.style.width = `${config.width}px`
      pane.style.height = `${config.height}px`
    }
    pane.style.zIndex = `${layer}`

    const head = headRef.current

    const onPanePointerDown = () => {
      layer++
      pane.style.zIndex = `${layer}`
    }

    let moving = false
    const onHeadPointerDown = e => {
      moving = true
    }

    const onPointerMove = e => {
      if (!moving) return
      config.x += e.movementX
      config.y += e.movementY
      pane.style.top = `${config.y}px`
      pane.style.left = `${config.x}px`
      persist()
    }

    const onPointerUp = e => {
      moving = false
    }

    const resizer = new ResizeObserver(entries => {
      const entry = entries[0]
      if (entry && entry.contentRect.width > 0 && entry.contentRect.height > 0) {
        config.width = entry.contentRect.width
        config.height = entry.contentRect.height
        persist()
      }
    })

    head.addEventListener('pointerdown', onHeadPointerDown)
    pane.addEventListener('pointerdown', onPanePointerDown)
    window.addEventListener('pointermove', onPointerMove)
    window.addEventListener('pointerup', onPointerUp)
    resizer.observe(pane)

    return () => {
      head.removeEventListener('pointerdown', onHeadPointerDown)
      pane.removeEventListener('pointerdown', onPanePointerDown)
      window.removeEventListener('pointermove', onPointerMove)
      window.removeEventListener('pointerup', onPointerUp)
      resizer.disconnect()
    }
  }, [])
}

import { useEffect, useState } from 'react'

export function useRank(world, player) {
  const [perms, setPerms] = useState(() => {
    const isAdmin = player.isAdmin()
    const isBuilder = player.isBuilder()
    return { isAdmin, isBuilder }
  })
  useEffect(() => {

function update() {
      const isAdmin = player.isAdmin()
      const isBuilder = player.isBuilder()
      setPerms({ isAdmin, isBuilder })
    }

function onSettings(changes) {
      if (changes.rank) {
        update()
      }
    }

function onRank({ playerId }) {
      if (player.data.id === playerId) {
        update()
      }
    }
    world.settings.on('change', onSettings)
    world.on('rank', onRank)
    return () => {
      world.settings.off('change', onSettings)
      world.off('rank', onRank)
    }
  }, [])

import { useState } from 'react'

export function useUpdate() {
  const [v, setV] = useState(0)
  return () => setV(v => v + 1)
