  //       const m1 = this.keyframes[i + 1].inMagnitude * (this.keyframes[i + 1].time - this.keyframes[i].time) // prettier-ignore
  //       const t2 = t * t
  //       const t3 = t2 * t

  //       const a = 2 * t3 - 3 * t2 + 1
  //       const b = t3 - 2 * t2 + t
  //       const c = -2 * t3 + 3 * t2
