  //   evaluate(t) {
  //     const keyframes = this.keyframes
  //     const n = keyframes.length
  //     const lo = this.getClosest(t)[0]
  //     let i0 = lo
  //     let i1 = i0 + 1

  //     if (i0 > n - 1) throw new Error('Out of bounds')
  //     if (i0 === n - 1) i1 = i0

  //     let scale = keyframes[i1].time - keyframes[i0].time

  //     t = (t - keyframes[i0].time) / scale

  //     let t2 = t * t
