import { System } from './System'

/**
 * Avatars System
 *
 * - Runs rate checks one avatar per frame (amortization)
 *
 */
export class Avatars extends System {
  constructor(world) {
    super(world)
    this.avatars = []
    this.cursor = 0
  }

  add(avatar) {
    this.avatars.push(avatar)
  }

  remove(avatar) {
    const idx = this.avatars.indexOf(avatar)
    if (idx === -1) return
    this.avatars.splice(idx, 1)
  }

  update() {
    if (!this.avatars.length) return
    const avatar = this.avatars[this.cursor % this.avatars.length]
    avatar.updateRate()
    this.cursor++
  }

  destroy() {
    this.avatars = []
  }
}

import { isEqual, merge } from 'lodash-es'
import { System } from './System'

/**
 * Blueprints System
 *
 * - Runs on both the server and client.
 * - A central registry for app blueprints
 *
 */
export class Blueprints extends System {
  constructor(world) {
    super(world)
    this.items = new Map()
  }

  get(id) {
    return this.items.get(id)
  }

  getScene() {
    return this.items.get('$scene')
  }

  add(data, local) {
    this.items.set(data.id, data)
    if (local) {
      this.world.network.send('blueprintAdded', data)
    }
  }

  modify(data) {
    const blueprint = this.items.get(data.id)
    const modified = {
      ...blueprint,
      ...data,
    }
    const changed = !isEqual(blueprint, modified)
    if (!changed) return
    this.items.set(blueprint.id, modified)
    for (const [_, entity] of this.world.entities.items) {
      if (entity.data.blueprint === blueprint.id) {
        entity.data.state = {}
        entity.build()
      }
    }
    this.emit('modify', modified)
  }

  serialize() {
    const datas = []
    this.items.forEach(data => {
      datas.push(data)
    })
    return datas
  }

  deserialize(datas) {
    for (const data of datas) {
      this.add(data)
    }
  }

  destroy() {
    this.items.clear()
  }
}

import { System } from './System'

/**
 * CameraManager System
 *
 * Manages all camera nodes in the world, tracking which is active
 * and handling transitions between cameras.
 */
export class CameraManager extends System {
  constructor(world) {
    super(world)

    // All registered cameras
    this.cameras = new Map()

    // Currently active camera
    this.activeCamera = null

    // Default/fallback camera (first registered)
    this.defaultCamera = null

    // Transition state
    this.isTransitioning = false
    this.transitionFrom = null
    this.transitionTo = null
    this.transitionProgress = 0
    this.transitionDuration = 0
    this.transitionEasing = 'linear'
  }

  /**
   * Register a camera node
   */
  registerCamera(camera) {
    if (!camera || !camera.id) {
      console.warn('CameraManager: Invalid camera registration attempt')
      return
    }

    this.cameras.set(camera.id, camera)

    // Set as default if first camera
    if (!this.defaultCamera) {
      this.defaultCamera = camera
    }

    // Activate if marked as active and no other camera is active
    if (camera.active && !this.activeCamera) {
      this.setActiveCamera(camera)
    }

    console.log(`CameraManager: Registered camera ${camera.id}`)
  }

  /**
   * Unregister a camera node
   */
  unregisterCamera(camera) {
    if (!camera || !camera.id) return

    console.log(`CameraManager: Unregistering camera ${camera.id} (${camera.name})`)

    // Don't allow unregistering the world's default camera
    if (camera === this.world?.defaultCameraNode) {
      console.warn('CameraManager: Cannot unregister world default camera')
      return
    }

    this.cameras.delete(camera.id)

    // Handle if this was the active camera
    if (this.activeCamera === camera) {
      this.activeCamera = null
      // Switch to default camera if available
      if (this.defaultCamera && this.defaultCamera !== camera) {
        this.setActiveCamera(this.defaultCamera)
      } else if (this.cameras.size > 0) {
        // No default camera, pick the first available one
        const firstCamera = this.cameras.values().next().value
        if (firstCamera) {
          this.setActiveCamera(firstCamera)
        }
      } else {
        // No cameras left, emit event to fall back to legacy camera
        console.log('CameraManager: No cameras remaining, falling back to legacy camera')
        this.world.emit('camera-manager-empty')
      }
    }

    // Handle if this was the default camera
    if (this.defaultCamera === camera) {
      this.defaultCamera = this.cameras.values().next().value || null
    }

    console.log(`CameraManager: Unregistered camera ${camera.id}`)
  }

  /**
   * Set the active camera
   */
  setActiveCamera(camera, transition = false, duration = 1) {
    if (!camera || !this.cameras.has(camera.id)) {
      console.warn('CameraManager: Attempted to activate unregistered camera')
      return false
    }

    // Deactivate current render camera without unmounting the node
    if (this.activeCamera && this.activeCamera !== camera) {
      if (this.activeCamera.makeInactive) {
        this.activeCamera.makeInactive()
      }
    }

    // Handle transition
    if (transition && this.activeCamera && this.activeCamera !== camera) {
      this.startTransition(this.activeCamera, camera, duration)
    } else {
      // Immediate switch
      this.activeCamera = camera
      // Only prepare camera local state here; do not recurse back into manager
      camera._active = true
      this.world.emit('camera-changed', camera)
    }

    console.log(`CameraManager: Activated camera ${camera.id}`)
    return true
  }

  /**
   * Get camera by ID
   */
  getCamera(id) {
    return this.cameras.get(id)
  }

  /**
   * Get all cameras
   */
  getAllCameras() {
    return Array.from(this.cameras.values())
  }

  /**
   * Start a camera transition
   */
  startTransition(from, to, duration = 1, easing = 'smooth') {
    this.isTransitioning = true
    this.transitionFrom = from
    this.transitionTo = to
    this.transitionProgress = 0
    this.transitionDuration = duration
    this.transitionEasing = easing

    // Mark both cameras as partially active during transition
    from.active = true
    to.active = true

    this.world.emit('camera-transition-start', { from, to, duration })
  }

  /**
   * Update transition
   */
  updateTransition(delta) {
    if (!this.isTransitioning) return

    this.transitionProgress += delta / this.transitionDuration

    if (this.transitionProgress >= 1) {
      // Transition complete
      this.completeTransition()
    } else {
      // Apply easing
      let t = this.transitionProgress
      if (this.transitionEasing === 'smooth') {
        t = t * t * (3 - 2 * t) // smoothstep
      } else if (this.transitionEasing === 'ease-in') {
        t = t * t
      } else if (this.transitionEasing === 'ease-out') {
        t = 1 - (1 - t) * (1 - t)
      }

      // Emit progress for systems that need to interpolate
      this.world.emit('camera-transition-progress', {
        from: this.transitionFrom,
        to: this.transitionTo,
        progress: t,
      })
    }
  }

  /**
   * Complete the current transition
   */
  completeTransition() {
    if (!this.isTransitioning) return

    // Deactivate old camera
    if (this.transitionFrom) {
      this.transitionFrom.active = false
    }

    // Fully activate new camera
    this.activeCamera = this.transitionTo
    if (this.transitionTo) {
      this.transitionTo.active = true
    }

    // Clear transition state
    this.isTransitioning = false
    this.transitionFrom = null
    this.transitionTo = null
    this.transitionProgress = 0

    this.world.emit('camera-transition-complete', this.activeCamera)
    this.world.emit('camera-changed', this.activeCamera)
  }

  /**
   * Update loop
   */
  update(delta) {
    // Update camera transition if in progress
    if (this.isTransitioning) {
      this.updateTransition(delta)
    }

    // Update aspect ratios if window resized
    if (this.world.graphics?.resized) {
      const aspect = this.world.graphics.aspect
      this.cameras.forEach(camera => {
        if (camera.aspect !== aspect) {
          camera.setAspect(aspect)
        }
      })
    }

    // Update active camera (for autofocus, etc)
    if (this.activeCamera && this.activeCamera.update) {
      this.activeCamera.update(delta)
    }

    // Update feeds for all cameras that have them enabled
    // Keep it lightweight: only render feeds when postprocessing is not busy rendering
    const renderer = this.world.graphics?.renderer
    if (renderer) {
      this.cameras.forEach(cam => {
        if (cam && cam.updateFeed) cam.updateFeed(delta)
      })
    }
  }

  /**
   * Get the camera to use for rendering
   * Returns active camera's THREE camera, or null
   */
  getRenderCamera() {
    if (this.isTransitioning) {
      // During transition, return the target camera
      // (Graphics system will handle blending if needed)
      return this.transitionTo?.camera || null
    }

    return this.activeCamera?.camera || null
  }

  /**
   * Check if a camera is currently active
   */
  isActive(camera) {
    return (
      camera === this.activeCamera ||
      (this.isTransitioning && (camera === this.transitionFrom || camera === this.transitionTo))
    )
  }

  /**
   * Get camera info for debugging
   */
  getDebugInfo() {
    return {
      totalCameras: this.cameras.size,
      activeCamera: this.activeCamera?.id || 'none',
      defaultCamera: this.defaultCamera?.id || 'none',
      isTransitioning: this.isTransitioning,
      transitionProgress: this.isTransitioning ? `${(this.transitionProgress * 100).toFixed(1)}%` : 'n/a',
    }
  }
}

import moment from 'moment'
import { uuid } from '../utils'
import { System } from './System'

/**
 * Chat System
 *
 * - Runs on both the server and client.
 * - Stores and handles chat messages
 * - Provides subscribe hooks for client UI
 *
 */

const CHAT_MAX_MESSAGES = 50

export class Chat extends System {
  constructor(world) {
    super(world)
    this.msgs = []
    this.listeners = new Set()
  }

  add(msg, broadcast) {
    if (!msg.id) msg.id = uuid()
    if (!msg.createdAt) moment().toISOString()
    // add to chat messages
    this.msgs = [...this.msgs, msg]
    if (this.msgs.length > CHAT_MAX_MESSAGES) {
      this.msgs.shift()
    }
    for (const callback of this.listeners) {
      callback(this.msgs)
    }
    if (msg.fromId) {
      const player = this.world.entities.getPlayer(msg.fromId)
      player?.chat(msg.body)
    }
    // emit chat event
    const readOnly = Object.freeze({ ...msg })
    this.world.events.emit('chat', readOnly)
    // maybe broadcast
    if (broadcast) {
      this.world.network.send('chatAdded', msg)
    }
  }

  command(text) {
    if (this.world.network.isServer) return
    const playerId = this.world.network.id
    const args = text
      .slice(1)
      .split(' ')
      .map(str => str.trim())
      .filter(str => !!str)
    const isAdminCommand = args[0] === 'admin'
    if (args[0] === 'stats') {
      this.world.prefs.setStats(!this.world.prefs.stats)
    }
    if (!isAdminCommand) {
      this.world.events.emit('command', { playerId, args })
    }
    this.world.network.send('command', args)
  }

  clear(broadcast) {
    this.msgs = []
    for (const callback of this.listeners) {
      callback(this.msgs)
    }
    if (broadcast) {
      this.world.network.send('chatCleared')
    }
  }

  send(text) {
    // only available as a client
    if (!this.world.network.isClient) return
    const player = this.world.entities.player
    const data = {
      id: uuid(),
      from: player.data.name,
      fromId: player.data.id,
      body: text,
      createdAt: moment().toISOString(),
    }
    this.add(data, true)
    return data
  }

  serialize() {
    return this.msgs
  }

  deserialize(msgs) {
    this.msgs = msgs
    for (const callback of this.listeners) {
      callback(msgs)
    }
  }

  subscribe(callback) {
    this.listeners.add(callback)
    callback(this.msgs)
    return () => {
      this.listeners.delete(callback)
    }
  }

  destroy() {
    this.msgs = []
    this.listeners.clear()
  }
}

import { System } from './System'

import * as THREE from '../extras/three'
import { initYoga } from '../extras/yoga'

let worker

/**
 * Client System
 *
 * - Runs on the client
 *
 *
 */
export class Client extends System {
  constructor(world) {
    super(world)
    window.world = world
    window.THREE = THREE
    // quick debug helpers exposed in console (guarded)
    try {
      Object.defineProperty(window.world, 'debug', {
        get: () => ({
          octree: {
            toggle: enabled => this.world.stage.octree.toggleHelper(enabled),
            depth: () => this.world.stage.octree.getDepth(),
            count: () => this.world.stage.octree.getCount(),
          },
          springs: () => {
            try {
              const inst = this.world.entities.player?.avatar?.instance
              return inst?.debug?.listSprings?.()
            } catch (_) {}
            return []
          },
          springAxes: (size, color) => {
            try {
              const inst = this.world.entities.player?.avatar?.instance
              return inst?.debug?.showSpringAxes?.(size, color)
            } catch (_) {}
            return []
          },
        }),
        configurable: true,
      })
    } catch (_) {}
  }

  async init({ loadYoga }) {
    await loadYoga
    initYoga()
  }

  start() {
    this.world.graphics.renderer.setAnimationLoop(this.world.tick)
    document.addEventListener('visibilitychange', this.onVisibilityChange)

    this.world.settings.on('change', this.onSettingsChange)
  }

  onSettingsChange = changes => {
    if (changes.title) {
      document.title = changes.title.value || 'World'
    }
  }

  onVisibilityChange = () => {
    // if the tab is no longer active, browsers stop triggering requestAnimationFrame.
    // this is obviously bad because physics stop running and we stop processing websocket messages etc.
    // instead, we stop using requestAnimationFrame and get a worker to tick at a slower rate using setInterval
    // and notify us.
    // this allows us to keep everything running smoothly.
    // See: https://gamedev.stackexchange.com/a/200503 (kinda fucking genius)
    //
    // spawn worker if we haven't yet
    if (!worker) {
      const script = `
        const rate = 1000 / 5 // 5 FPS
        let intervalId = null;
        self.onmessage = e => {
          if (e.data === 'start' && !intervalId) {
            intervalId = setInterval(() => {
              self.postMessage(1);
            }, rate);
            console.log('[worker] tick started')
          }
          if (e.data === 'stop' && intervalId) {
            clearInterval(intervalId);
            intervalId = null;
            console.log('[worker] tick stopped')
          }
        }
      `
      const blob = new Blob([script], { type: 'application/javascript' })
      worker = new Worker(URL.createObjectURL(blob))
      worker.onmessage = () => {
        const time = performance.now()
        this.world.tick(time)
      }
    }
    if (document.hidden) {
      // stop rAF
      this.world.graphics.renderer.setAnimationLoop(null)
      // tell the worker to start
      worker.postMessage('start')
    } else {
      // tell the worker to stop
      worker.postMessage('stop')
      // resume rAF
      this.world.graphics.renderer.setAnimationLoop(this.world.tick)
    }
  }

  destroy() {
    this.world.graphics.renderer.setAnimationLoop(null)
    worker?.postMessage('stop')
    worker = null
    document.removeEventListener('visibilitychange', this.onVisibilityChange)
  }
}

import * as THREE from 'three'

import { System } from './System'
import { ControlPriorities } from '../extras/ControlPriorities'
import { isTouch } from '../../client/utils'
import { clamp } from '../utils'

const BATCH_SIZE = 500
const FORWARD = new THREE.Vector3(0, 0, 1)

const v1 = new THREE.Vector3()
const v2 = new THREE.Vector3()
const v3 = new THREE.Vector3()
const v4 = new THREE.Vector3()
const v5 = new THREE.Vector3()
const q1 = new THREE.Quaternion()
const e1 = new THREE.Euler(0, 0, 0, 'YXZ')
const m1 = new THREE.Matrix4()

export class ClientActions extends System {
  constructor(world) {
    super(world)
    this.nodes = []
    this.cursor = 0
    this.current = {
      node: null,
      distance: Infinity,
    }
    this.action = null
  }

  start() {
    this.action = createAction(this.world)
    this.btnDown = false
    this.control = this.world.controls.bind({ priority: ControlPriorities.ACTION })
  }

  register(node) {
    this.nodes.push(node)
  }

  unregister(node) {
    const idx = this.nodes.indexOf(node)
    if (idx === -1) return
    this.nodes.splice(idx, 1)
    if (this.current.node === node) {
      this.current.node = null
      this.current.distance = Infinity
      this.action.stop()
    }
  }

  update(delta) {
    const cameraPos = this.world.rig.position

    this.btnDown =
      this.control.keyE.down ||
      this.control.touchB.down ||
      this.control.xrLeftTrigger.down ||
      this.control.xrRightTrigger.down

    // clear current action if its no longer in distance
    if (this.current.node) {
      const distance = this.current.node.worldPos.distanceTo(cameraPos)
      if (distance > this.current.node._distance) {
        this.current.node = null
        this.current.distance = Infinity
        this.emit('change', false)
        this.action.stop()
      } else {
        this.current.distance = distance
      }
    }

    // continually check nodes[] in batches to find the one that should be active
    let didChange
    const size = Math.min(this.nodes.length, BATCH_SIZE)
    for (let i = 0; i < size; i++) {
      const idx = (this.cursor + i) % this.nodes.length
      const node = this.nodes[idx]
      if (node.finished) continue
      if (this.current.node === node) continue
      const distance = node.worldPos.distanceTo(cameraPos)
      if (distance <= node._distance && distance < this.current.distance) {
        this.current.node = node
        this.current.distance = distance
        didChange = true
      }
    }
    if (size) {
      this.cursor = (this.cursor + size) % this.nodes.length
    }
    if (didChange) {
      this.action.start(this.current.node)
      this.emit('change', true)
    }
    this.action.update(delta)
  }

  destroy() {
    this.control.release()
    this.control = null
    this.nodes = []
  }
}

function createAction(world) {
  const widthPx = 300
  const heightPx = 44
  const pxToMeters = 0.01
  const board = createBoard(widthPx, heightPx, pxToMeters, world)

  const draw = (label, ratio) => {
    // console.time('draw')
    const text = board.measureText(47, heightPx / 2, label, '#ffffff', 18, 400)
    const pillWidth = 6 + 4 + 24 + 4 + 6 + 9 + text.width + 13
    const left = (widthPx - pillWidth) / 2
    board.clear()
    board.drawBox(left, 0, pillWidth, heightPx, heightPx / 2, 'rgba(11, 10, 21, 0.97)')
    board.drawPie(left + 6, 6, 16, 100, '#5d6077') // grey
    board.drawPie(left + 6, 6, 16, ratio * 100, '#ffffff') // white
    board.drawCircle(left + 10, 10, 12, '#000000') // inner
    if (!isTouch) board.drawText(left + 16, 14, 'E', '#ffffff', 18, 400) // E
    board.drawText(left + 47, 14, label, '#ffffff', 18, 400) // label
    board.commit()
    // console.timeEnd('draw')
  }

  const mesh = board.getMesh()

  // debug
  // board.canvas.style = 'position:absolute; top:70px; left:30px; z-index:999; pointer-events:none; transform:scale(1); transform-origin:top left;' // prettier-ignore
  // document.body.appendChild(board.canvas)

  let node = null
  let cancelled = false

  return {
    start(_node) {
      // if (node) console.error('erm node already set')
      node = _node
      world.actions.btnDown = false
      node.progress = 0
      draw(node._label, node.progress / node._duration)
      world.stage.scene.add(mesh)
    },
    update(delta) {
      if (!node) return
      let distance
      if (world.xr.session) {
        const pos = v1
        const qua = q1
        const sca = v2
        node.matrixWorld.decompose(pos, qua, sca)
        const camPosition = v3.setFromMatrixPosition(world.xr.camera.matrixWorld)
        distance = camPosition.distanceTo(pos)
        v4.subVectors(camPosition, pos).normalize()
        qua.setFromUnitVectors(FORWARD, v4)
        e1.setFromQuaternion(qua)
        e1.z = 0
        qua.setFromEuler(e1)
        mesh.position.copy(pos)
        mesh.quaternion.copy(qua)
        mesh.scale.copy(sca)
      } else {
        const camPosition = v3.setFromMatrixPosition(world.camera.matrixWorld)
        mesh.position.setFromMatrixPosition(node.matrixWorld)
        distance = camPosition.distanceTo(mesh.position)
        mesh.quaternion.setFromRotationMatrix(world.camera.matrixWorld)
      }
      const worldToScreenFactor = world.graphics.worldToScreenFactor
      const [minDistance, maxDistance, baseScale = 1] = [3, 5, 1]
      const clampedDistance = clamp(distance, minDistance, maxDistance)
      // calculate scale factor based on the distance
      // When distance is at min, scale is 1.0 (or some other base scale)
      // When distance is at max, scale adjusts proportionally
      let scaleFactor = baseScale * (worldToScreenFactor * clampedDistance) * 100
      if (world.xr.session) scaleFactor *= 0.2 // shrink because its HUGE in VR
      mesh.scale.setScalar(scaleFactor)
      if (world.actions.btnDown) {
        if (node.progress === 0) {
          cancelled = false
          try {
            node._onStart()
          } catch (err) {
            console.error('action.onStart:', err)
          }
        }
        node.progress += delta
        if (node.progress > node._duration) node.progress = node._duration
        draw(node._label, node.progress / node._duration)
        if (node.progress === node._duration) {
          node.progress = 0
          try {
            node._onTrigger({ playerId: world.entities.player.data.id })
          } catch (err) {
            console.error('action.onTrigger:', err)
          }
        }
      } else if (node.progress > 0) {
        if (!cancelled) {
          try {
            node._onCancel()
          } catch (err) {
            console.error('action.onCancel:', err)
          }
          cancelled = true
        }
        node.progress -= delta
        if (node.progress < 0) node.progress = 0
        draw(node._label, node.progress / node._duration)
      }
    },
    stop() {
      node = null
      if (mesh.parent) {
        world.stage.scene.remove(mesh)
      }
    },
  }
}

function createBoard(width, height, pxToMeters, world) {
  const max = Math.max(width, height)
  const size = sizes.find(size => size >= max)
  const pr = 1 // window.devicePixelRatio
  const canvas = document.createElement('canvas')
  canvas.width = size * pr
  canvas.height = size * pr
  // console.log('board', canvas.width, canvas.height)
  const ctx = canvas.getContext('2d')

  let texture
  let mesh

  return {
    canvas,
    drawBox(x, y, width, height, radius, color) {
      x *= pr
      y *= pr
      width *= pr
      height *= pr
      radius *= pr
      ctx.fillStyle = color
      ctx.beginPath()
      ctx.moveTo(x + radius, y) // start left center
      ctx.arcTo(x + width, y, x + width, y + height, radius) // right edge
      ctx.arcTo(x + width, y + height, x, y + height, radius) // bottom edge
      ctx.arcTo(x, y + height, x, y, radius) // left edge
      ctx.arcTo(x, y, x + width, y, radius) // top edge
      ctx.closePath()
      ctx.fill()
    },
    drawCircle(x, y, radius, color) {
      x *= pr
      y *= pr
      radius *= pr
      const centerX = x + radius
      const centerY = y + radius
      ctx.beginPath()
      ctx.arc(centerX, centerY, radius, 0, 2 * Math.PI)
      ctx.fillStyle = color
      ctx.fill()
    },
    drawPie(x, y, radius, percent, color, offset = 0) {
      x *= pr
      y *= pr
      radius *= pr
      const offsetRadians = (offset * Math.PI) / 180
      const startAngle = -0.5 * Math.PI + offsetRadians
      const endAngle = startAngle + (percent / 100) * 2 * Math.PI
      ctx.beginPath()
      ctx.moveTo(x + radius, y + radius)
      ctx.arc(x + radius, y + radius, radius, startAngle, endAngle)
      ctx.lineTo(x + radius, y + radius)
      ctx.closePath()
      ctx.fillStyle = color
      ctx.fill()
    },
    measureText(x, y, text, color, fontSize = 16, fontWeight = 400, font = 'Rubik') {
      fontSize *= pr
      ctx.font = `${fontWeight} ${fontSize}px ${font}`
      const metrics = ctx.measureText(text)
      return {
        width: metrics.width / pr,
      }
    },
    drawText(x, y, text, color, fontSize = 16, fontWeight = 400, font = 'Rubik') {
      x *= pr
      y *= pr
      // y -= fontSize / 2 // no idea why but yup
      fontSize *= pr
      ctx.fillStyle = color
      ctx.font = `${fontWeight} ${fontSize}px ${font}`
      ctx.textAlign = 'left'
      ctx.textBaseline = 'top'
      ctx.fillText(text, x, y)
    },
    getMesh() {
      if (mesh) return mesh
      const offsetX = 0 // top left for now
      const offsetY = 0
      texture = new THREE.CanvasTexture(canvas)
      texture.colorSpace = THREE.SRGBColorSpace
      texture.anisotropy = world.graphics.maxAnisotropy
      // texture.minFilter = texture.magFilter = THREE.LinearFilter
      texture.minFilter = THREE.LinearFilter
      texture.magFilter = THREE.LinearFilter
      // texture.generateMipmaps = false
      const geometry = new THREE.BufferGeometry()
      const halfWidth = (width * pxToMeters) / 2
      const halfHeight = (height * pxToMeters) / 2
      // prettier-ignore
      const vertices = new Float32Array([
        halfWidth, -halfHeight, 0,  // vertex 3 (bottom right)
        halfWidth, halfHeight, 0,   // vertex 2 (top right)
        -halfWidth, halfHeight, 0,  // vertex 1 (top left)
        -halfWidth, -halfHeight, 0, // vertex 0 (bottom left)
      ])
      geometry.setAttribute('position', new THREE.BufferAttribute(vertices, 3))
      const uvX1 = offsetX / size
      const uvY1 = 1 - offsetY / size
      const uvX2 = (offsetX + width) / size
      const uvY2 = 1 - (offsetY + height) / size
      // prettier-ignore
      const uvs = new Float32Array([
        uvX2, uvY2,  // UV for vertex 3
        uvX2, uvY1,  // UV for vertex 2
        uvX1, uvY1,  // UV for vertex 1
        uvX1, uvY2,  // UV for vertex 0
      ])
      geometry.setAttribute('uv', new THREE.BufferAttribute(uvs, 2))
      // prettier-ignore
      const indices = new Uint16Array([
        0, 1, 2,  // First triangle
        2, 3, 0   // Second triangle
      ])
      geometry.setIndex(new THREE.BufferAttribute(indices, 1))
      const material = new THREE.MeshBasicMaterial({ map: texture })
      material.toneMapped = false
      // create mesh
      mesh = new THREE.Mesh(geometry, material)
      // console.log(mesh)
      // always on top
      material.depthTest = false
      material.depthWrite = false
      material.transparent = true
      mesh.renderOrder = 999
      return mesh
    },
    commit() {
      if (!texture) return
      texture.needsUpdate = true
    },
    clear() {
      ctx.clearRect(0, 0, canvas.width, canvas.height)
    },
  }
}

import * as THREE from '../extras/three'

import { System } from './System'

const up = new THREE.Vector3(0, 1, 0)
const v1 = new THREE.Vector3()

export class ClientAudio extends System {
  constructor(world) {
    super(world)
    this.handles = new Set()
    this.ctx = new AudioContext() // new (window.AudioContext || window.webkitAudioContext)();
    this.masterGain = this.ctx.createGain()
    this.masterGain.connect(this.ctx.destination)
    this.groupGains = {
      music: this.ctx.createGain(),
      sfx: this.ctx.createGain(),
      voice: this.ctx.createGain(),
    }
    this.groupGains.music.gain.value = world.prefs.music
    this.groupGains.sfx.gain.value = world.prefs.sfx
    this.groupGains.voice.gain.value = world.prefs.voice
    this.groupGains.music.connect(this.masterGain)
    this.groupGains.sfx.connect(this.masterGain)
    this.groupGains.voice.connect(this.masterGain)
    this.listener = this.ctx.listener
    this.listener.positionX.value = 0
    this.listener.positionY.value = 0
    this.listener.positionZ.value = 0
    this.listener.forwardX.value = 0
    this.listener.forwardY.value = 0
    this.listener.forwardZ.value = -1
    this.listener.upX.value = 0
    this.listener.upY.value = 1
    this.listener.upZ.value = 0
    this.lastDelta = 0

    this.queue = []
    this.unlocked = this.ctx.state !== 'suspended'
    if (!this.unlocked) {
      this.setupUnlockListener()
    }
  }

  ready(fn) {
    if (this.unlocked) return fn()
    this.queue.push(fn)
  }

  setupUnlockListener() {
    const complete = () => {
      this.unlocked = true
      document.removeEventListener('click', unlock)
      document.removeEventListener('touchstart', unlock)
      document.removeEventListener('keydown', unlock)
      while (this.queue.length) {
        this.queue.pop()()
      }
      console.log('[audio] unlocked')
    }
    const unlock = async () => {
      try {
        await this.ctx.resume()
        if (this.ctx.state !== 'running') throw new Error('Audio still suspended')
        const video = document.createElement('video')
        video.playsInline = true
        video.muted = true
        video.src = '/tiny.mp4'
        video
          .play()
          .then(() => {
            video.pause()
            video.remove()
            console.log('[audio] video played')
          })
          .catch(err => {
            console.log('[audio] video failed')
          })
      } catch (err) {
        console.error(err)
      } finally {
        // either way, mark the system as unlocked
        complete()
      }
    }
    document.addEventListener('click', unlock)
    document.addEventListener('touchstart', unlock)
    document.addEventListener('keydown', unlock)
    console.log('[audio] suspended, waiting for interact...')
  }

  async init() {
    this.world.prefs.on('change', this.onPrefsChange)
  }

  start() {
    // ...
  }

  lateUpdate(delta) {
    const target = this.world.rig
    const dir = v1.set(0, 0, -1).applyQuaternion(target.quaternion)
    if (this.listener.positionX) {
      // https://github.com/mrdoob/three.js/blob/master/src/audio/AudioListener.js
      // code path for Chrome (see three#14393)
      const endTime = this.ctx.currentTime + delta * 2
      this.listener.positionX.linearRampToValueAtTime(target.position.x, endTime)
      this.listener.positionY.linearRampToValueAtTime(target.position.y, endTime)
      this.listener.positionZ.linearRampToValueAtTime(target.position.z, endTime)
      this.listener.forwardX.linearRampToValueAtTime(dir.x, endTime)
      this.listener.forwardY.linearRampToValueAtTime(dir.y, endTime)
      this.listener.forwardZ.linearRampToValueAtTime(dir.z, endTime)
      this.listener.upX.linearRampToValueAtTime(up.x, endTime)
      this.listener.upY.linearRampToValueAtTime(up.y, endTime)
      this.listener.upZ.linearRampToValueAtTime(up.z, endTime)
    } else {
      this.listener.setPosition(target.position.x, target.position.y, target.position.z)
      this.listener.setOrientation(dir.x, dir.y, dir.z, up.x, up.y, up.z)
    }
    this.lastDelta = delta * 2
  }

  onPrefsChange = changes => {
    if (changes.music) {
      this.groupGains.music.gain.value = changes.music.value
    }
    if (changes.sfx) {
      this.groupGains.sfx.gain.value = changes.sfx.value
    }
    if (changes.voice) {
      this.groupGains.voice.gain.value = changes.voice.value
    }
  }

  destroy() {
    this.groupGains.music.disconnect()
    this.groupGains.sfx.disconnect()
    this.groupGains.voice.disconnect()
    this.masterGain.disconnect()
    this.ctx.close()
    this.handles.clear()
    this.queue = []
  }
}

import moment from 'moment'
import * as THREE from '../extras/three'
import { cloneDeep, isBoolean } from 'lodash-es'
import { TransformControls } from 'three/examples/jsm/controls/TransformControls.js'

import { System } from './System'

import { hashFile } from '../utils-client'
import { uuid } from '../utils'
import { ControlPriorities } from '../extras/ControlPriorities'
import { importApp } from '../extras/appTools'
import { DEG2RAD, RAD2DEG } from '../extras/general'

const FORWARD = new THREE.Vector3(0, 0, -1)
const SNAP_DISTANCE = 1
const SNAP_DEGREES = 5
const PROJECT_SPEED = 10
const PROJECT_MIN = 3
const PROJECT_MAX = 50

const v1 = new THREE.Vector3()
const q1 = new THREE.Quaternion()
const e1 = new THREE.Euler()

const modeLabels = {
  grab: 'Grab',
  translate: 'Translate',
  rotate: 'Rotate',
  scale: 'Scale',
}

/**
 * Builder System
 *
 * - runs on the client
 * - listens for files being drag and dropped onto the window and handles them
 * - handles build mode
 *
 */
export class ClientBuilder extends System {
  constructor(world) {
    super(world)
    this.enabled = false
    this.selected = null
    this.mode = 'grab'
    this.localSpace = false
    this.target = new THREE.Object3D()
    this.target.rotation.reorder('YXZ')
    this.lastMoveSendTime = 0

    this.undos = []

    this.dropTarget = null
    this.file = null
  }

  async init({ viewport }) {
    this.viewport = viewport
    this.viewport.addEventListener('dragover', this.onDragOver)
    this.viewport.addEventListener('dragenter', this.onDragEnter)
    this.viewport.addEventListener('dragleave', this.onDragLeave)
    this.viewport.addEventListener('drop', this.onDrop)
    this.world.on('player', this.checkLocalPlayer)
    this.world.settings.on('change', this.checkLocalPlayer)
  }

  start() {
    this.control = this.world.controls.bind({ priority: ControlPriorities.BUILDER })
    this.control.mouseLeft.onPress = () => {
      // pointer lock requires user-gesture in safari
      // so this can't be done during update cycle
      if (!this.control.pointer.locked) {
        this.control.pointer.lock()
        this.justPointerLocked = true
        return true // capture
      }
    }
    this.updateActions()
  }

  checkLocalPlayer = () => {
    if (this.enabled && !this.canBuild()) {
      // builder revoked
      this.select(null)
      this.enabled = false
      this.world.emit('build-mode', false)
    }
    this.updateActions()
  }

  canBuild() {
    return this.world.entities.player?.isBuilder()
  }

  updateActions() {
    const actions = []
    if (!this.enabled) {
      if (this.canBuild()) {
        // actions.push({ type: 'tab', label: 'Build Mode' })
      }
    }
    if (this.enabled && !this.selected) {
      actions.push({ type: 'mouseLeft', label: modeLabels[this.mode] })
      actions.push({ type: 'mouseRight', label: 'Inspect' })
      actions.push({ type: 'custom', btn: '1234', label: 'Grab / Translate / Rotate / Scale' })
      actions.push({ type: 'keyR', label: 'Duplicate' })
      actions.push({ type: 'keyP', label: 'Pin' })
      actions.push({ type: 'keyX', label: 'Destroy' })
      actions.push({ type: 'space', label: 'Jump / Fly (Double-Tap)' })
      // actions.push({ type: 'tab', label: 'Exit Build Mode' })
    }
    if (this.enabled && this.selected && this.mode === 'grab') {
      actions.push({ type: 'mouseLeft', label: 'Place' })
      actions.push({ type: 'mouseWheel', label: 'Rotate' })
      actions.push({ type: 'mouseRight', label: 'Inspect' })
      actions.push({ type: 'custom', btn: '1234', label: 'Grab / Translate / Rotate / Scale' })
      actions.push({ type: 'keyF', label: 'Push' })
      actions.push({ type: 'keyC', label: 'Pull' })
      actions.push({ type: 'keyX', label: 'Destroy' })
      actions.push({ type: 'controlLeft', label: 'No Snap (Hold)' })
      actions.push({ type: 'space', label: 'Jump / Fly (Double-Tap)' })
      // actions.push({ type: 'tab', label: 'Exit Build Mode' })
    }
    if (
      this.enabled &&
      this.selected &&
      (this.mode === 'translate' || this.mode === 'rotate' || this.mode === 'scale')
    ) {
      actions.push({ type: 'mouseLeft', label: 'Select / Transform' })
      actions.push({ type: 'mouseRight', label: 'Inspect' })
      actions.push({ type: 'custom', btn: '1234', label: 'Grab / Translate / Rotate / Scale' })
      actions.push({ type: 'keyT', label: this.localSpace ? 'World Space' : 'Local Space' })
      actions.push({ type: 'keyX', label: 'Destroy' })
      actions.push({ type: 'controlLeft', label: 'No Snap (Hold)' })
      actions.push({ type: 'space', label: 'Jump / Fly (Double-Tap)' })
      // actions.push({ type: 'tab', label: 'Exit Build Mode' })
    }
    this.control.setActions(actions)
  }

  update(delta) {
    // toggle build
    if (this.control.tab.pressed) {
      this.toggle()
    }
    // deselect if dead
    if (this.selected?.destroyed) {
      this.select(null)
    }
    // deselect if stolen
    if (this.selected && this.selected?.data.mover !== this.world.network.id) {
      this.select(null)
    }
    // stop here if build mode not enabled
    if (!this.enabled) {
      return
    }
    // inspect in pointer-lock
    if (this.control.mouseRight.pressed && this.control.pointer.locked) {
      const entity = this.getEntityAtReticle()
      if (entity?.isApp) {
        this.select(null)
        this.control.pointer.unlock()
        this.world.ui.setApp(entity)
      }
      if (entity?.isPlayer) {
        this.select(null)
        this.control.pointer.unlock()
        this.world.ui.togglePane('players')
      }
    }
    // inspect out of pointer-lock
    else if (!this.selected && !this.control.pointer.locked && this.control.mouseRight.pressed) {
      const entity = this.getEntityAtPointer()
      if (entity?.isApp) {
        this.select(null)
        this.control.pointer.unlock()
        this.world.ui.setApp(entity)
      }
      if (entity?.isPlayer) {
        this.select(null)
        this.control.pointer.unlock()
        this.world.ui.togglePane('players')
      }
    }
    // unlink
    if (this.control.keyU.pressed && this.control.pointer.locked) {
      const entity = this.selected || this.getEntityAtReticle()
      if (entity?.isApp) {
        this.select(null)
        // duplicate the blueprint
        const blueprint = {
          id: uuid(),
          version: 0,
          name: entity.blueprint.name,
          image: entity.blueprint.image,
          author: entity.blueprint.author,
          url: entity.blueprint.url,
          desc: entity.blueprint.desc,
          model: entity.blueprint.model,
          script: entity.blueprint.script,
          props: cloneDeep(entity.blueprint.props),
          preload: entity.blueprint.preload,
          public: entity.blueprint.public,
          locked: entity.blueprint.locked,
          frozen: entity.blueprint.frozen,
          unique: entity.blueprint.unique,
          scene: entity.blueprint.scene,
          disabled: entity.blueprint.disabled,
        }
        this.world.blueprints.add(blueprint, true)
        // assign new blueprint
        entity.modify({ blueprint: blueprint.id })
        this.world.network.send('entityModified', { id: entity.data.id, blueprint: blueprint.id })
        // toast
        this.world.emit('toast', 'Unlinked')
      }
    }
    // pin/unpin
    if (this.control.keyP.pressed && this.control.pointer.locked) {
      const entity = this.selected || this.getEntityAtReticle()
      if (entity?.isApp) {
        entity.data.pinned = !entity.data.pinned
        this.world.network.send('entityModified', {
          id: entity.data.id,
          pinned: entity.data.pinned,
        })
        this.world.emit('toast', entity.data.pinned ? 'Pinned' : 'Un-pinned')
        this.select(null)
      }
    }
    // gizmo local/world toggle
    if (this.control.keyT.pressed & (this.mode === 'translate' || this.mode === 'rotate' || this.mode === 'scale')) {
      this.localSpace = !this.localSpace
      this.gizmo.space = this.localSpace ? 'local' : 'world'
      this.updateActions()
    }
    // grab mode
    if (this.control.digit1.pressed) {
      this.setMode('grab')
    }
    // translate mode
    if (this.control.digit2.pressed) {
      this.setMode('translate')
    }
    // rotate mode
    if (this.control.digit3.pressed) {
      this.setMode('rotate')
    }
    // scale mode
    if (this.control.digit4.pressed) {
      this.setMode('scale')
    }
    // left-click place/select/reselect/deselect
    if (!this.justPointerLocked && this.control.pointer.locked && this.control.mouseLeft.pressed) {
      // if nothing selected, attempt to select
      if (!this.selected) {
        const entity = this.getEntityAtReticle()
        if (entity?.isApp && !entity.data.pinned && !entity.blueprint.scene) this.select(entity)
      }
      // if selected in grab mode, place
      else if (this.selected && this.mode === 'grab') {
        this.select(null)
      }
      // if selected in translate/rotate/scale mode, re-select/deselect
      else if (
        this.selected &&
        (this.mode === 'translate' || this.mode === 'rotate' || this.mode === 'scale') &&
        !this.gizmoActive
      ) {
        const entity = this.getEntityAtReticle()
        if (entity?.isApp && !entity.data.pinned && !entity.blueprint.scene) this.select(entity)
        else this.select(null)
      }
    }
    // deselect on pointer unlock
    if (this.selected && !this.control.pointer.locked) {
      this.select(null)
    }
    // duplicate
    if (
      !this.justPointerLocked &&
      this.control.pointer.locked &&
      this.control.keyR.pressed &&
      !this.control.metaLeft.down &&
      !this.control.controlLeft.down
    ) {
      const entity = this.selected || this.getEntityAtReticle()
      if (entity?.isApp && !entity.blueprint.scene) {
        let blueprintId = entity.data.blueprint
        // if unique, we also duplicate the blueprint
        if (entity.blueprint.unique) {
          const blueprint = {
            id: uuid(),
            version: 0,
            name: entity.blueprint.name,
            image: entity.blueprint.image,
            author: entity.blueprint.author,
            url: entity.blueprint.url,
            desc: entity.blueprint.desc,
            model: entity.blueprint.model,
            script: entity.blueprint.script,
            props: cloneDeep(entity.blueprint.props),
            preload: entity.blueprint.preload,
            public: entity.blueprint.public,
            locked: entity.blueprint.locked,
            frozen: entity.blueprint.frozen,
            unique: entity.blueprint.unique,
            scene: entity.blueprint.scene,
            disabled: entity.blueprint.disabled,
          }
          this.world.blueprints.add(blueprint, true)
          blueprintId = blueprint.id
        }
        const data = {
          id: uuid(),
          type: 'app',
          blueprint: blueprintId,
          position: entity.root.position.toArray(),
          quaternion: entity.root.quaternion.toArray(),
          scale: entity.root.scale.toArray(),
          mover: this.world.network.id,
          uploader: null,
          pinned: false,
          state: {},
        }
        const dup = this.world.entities.add(data, true)
        this.select(dup)
        this.addUndo({
          name: 'remove-entity',
          entityId: data.id,
        })
      }
    }
    // destroy
    if (this.control.keyX.pressed) {
      const entity = this.selected || this.getEntityAtReticle()
      if (entity?.isApp && !entity.data.pinned && !entity.blueprint.scene) {
        this.select(null)
        this.addUndo({
          name: 'add-entity',
          data: cloneDeep(entity.data),
        })
        entity?.destroy(true)
      }
    }
    // undo
    if (
      this.control.keyZ.pressed &&
      !this.control.shiftLeft.down &&
      (this.control.metaLeft.down || this.control.controlLeft.down)
    ) {
      console.log('undo', {
        shiftLeft: this.control.shiftLeft.down,
        metaLeft: this.control.metaLeft.down,
        controlLeft: this.control.controlLeft.down,
      })
      this.undo()
    }
    // translate updates
    if (this.selected && this.mode === 'translate' && this.gizmoActive) {
      const app = this.selected
      app.root.position.copy(this.gizmoTarget.position)
      app.root.quaternion.copy(this.gizmoTarget.quaternion)
      app.root.scale.copy(this.gizmoTarget.scale)
    }
    // rotate updates
    if (this.selected && this.mode === 'rotate' && this.control.controlLeft.pressed) {
      this.gizmo.rotationSnap = null
    }
    if (this.selected && this.mode === 'rotate' && this.control.controlLeft.released) {
      this.gizmo.rotationSnap = SNAP_DEGREES * DEG2RAD
    }
    if (this.selected && this.mode === 'rotate' && this.gizmoActive) {
      const app = this.selected
      app.root.position.copy(this.gizmoTarget.position)
      app.root.quaternion.copy(this.gizmoTarget.quaternion)
      app.root.scale.copy(this.gizmoTarget.scale)
    }
    // scale updates
    if (this.selected && this.mode === 'scale' && this.gizmoActive) {
      const app = this.selected
      app.root.scale.copy(this.gizmoTarget.scale)
    }
    // grab updates
    if (this.selected && this.mode === 'grab') {
      const app = this.selected
      const hit = this.getHitAtReticle(app, true)
      // place at distance
      const camPos = this.world.rig.position
      const camDir = v1.copy(FORWARD).applyQuaternion(this.world.rig.quaternion)
      const hitDistance = hit ? hit.point.distanceTo(camPos) : 0
      if (hit && hitDistance < this.target.limit) {
        // within range, use hit point
        this.target.position.copy(hit.point)
      } else {
        // no hit, project to limit
        this.target.position.copy(camPos).add(camDir.multiplyScalar(this.target.limit))
      }
      // if holding F/C then push or pull
      let project = this.control.keyF.down ? 1 : this.control.keyC.down ? -1 : null
      if (project) {
        const multiplier = this.control.shiftLeft.down ? 4 : 1
        this.target.limit += project * PROJECT_SPEED * delta * multiplier
        if (this.target.limit < PROJECT_MIN) this.target.limit = PROJECT_MIN
        if (hitDistance && this.target.limit > hitDistance) this.target.limit = hitDistance
      }
      // shift + mouse wheel scales
      if (this.control.shiftLeft.down) {
        const scaleFactor = 1 + this.control.scrollDelta.value * 0.1 * delta
        this.target.scale.multiplyScalar(scaleFactor)
      }
      // !shift + mouse wheel rotates
      else {
        this.target.rotation.y += this.control.scrollDelta.value * 0.1 * delta
      }
      // apply movement
      app.root.position.copy(this.target.position)
      app.root.quaternion.copy(this.target.quaternion)
      app.root.scale.copy(this.target.scale)
      // snap rotation to degrees
      if (!this.control.controlLeft.down) {
        const newY = this.target.rotation.y
        const degrees = newY / DEG2RAD
        const snappedDegrees = Math.round(degrees / SNAP_DEGREES) * SNAP_DEGREES
        app.root.rotation.y = snappedDegrees * DEG2RAD
      }
      // update matrix
      app.root.clean()
      // and snap to any nearby points
      if (!this.control.controlLeft.down) {
        for (const pos of app.snaps) {
          const result = this.world.snaps.octree.query(pos, SNAP_DISTANCE)[0]
          if (result) {
            const offset = v1.copy(result.position).sub(pos)
            app.root.position.add(offset)
            break
          }
        }
      }
    }
    // send selected updates
    if (this.selected) {
      this.lastMoveSendTime += delta
      if (this.lastMoveSendTime > this.world.networkRate) {
        const app = this.selected
        this.world.network.send('entityModified', {
          id: app.data.id,
          position: app.root.position.toArray(),
          quaternion: app.root.quaternion.toArray(),
          scale: app.root.scale.toArray(),
        })
        this.lastMoveSendTime = 0
      }
    }

    if (this.justPointerLocked) {
      this.justPointerLocked = false
    }
  }

  addUndo(action) {
    this.undos.push(action)
    if (this.undos.length > 50) {
      this.undos.shift()
    }
  }

  undo() {
    const undo = this.undos.pop()
    if (!undo) return
    if (this.selected) this.select(null)
    if (undo.name === 'add-entity') {
      this.world.entities.add(undo.data, true)
      return
    }
    if (undo.name === 'move-entity') {
      const entity = this.world.entities.get(undo.entityId)
      if (!entity) return
      entity.data.position = undo.position
      entity.data.quaternion = undo.quaternion
      this.world.network.send('entityModified', {
        id: undo.entityId,
        position: entity.data.position,
        quaternion: entity.data.quaternion,
        scale: entity.data.scale,
      })
      entity.build()
      return
    }
    if (undo.name === 'remove-entity') {
      const entity = this.world.entities.get(undo.entityId)
      if (!entity) return
      entity.destroy(true)
      return
    }
  }

  toggle(enabled) {
    if (!this.canBuild()) return
    enabled = isBoolean(enabled) ? enabled : !this.enabled
    if (this.enabled === enabled) return
    this.enabled = enabled
    if (!this.enabled) this.select(null)
    this.updateActions()
    this.world.emit('build-mode', enabled)
  }

  setMode(mode) {
    // cleanup
    if (this.selected) {
      if (this.mode === 'grab') {
        this.control.keyC.capture = false
        this.control.scrollDelta.capture = false
      }
      if (this.mode === 'translate' || this.mode === 'rotate' || this.mode === 'scale') {
        this.detachGizmo()
      }
    }
    // change
    this.mode = mode
    if (this.mode === 'grab') {
      if (this.selected) {
        const app = this.selected
        this.control.keyC.capture = true
        this.control.scrollDelta.capture = true
        this.target.position.copy(app.root.position)
        this.target.quaternion.copy(app.root.quaternion)
        this.target.scale.copy(app.root.scale)
        this.target.limit = PROJECT_MAX
      }
    }
    if (this.mode === 'translate' || this.mode === 'rotate' || this.mode === 'scale') {
      if (this.selected) {
        this.attachGizmo(this.selected, this.mode)
      }
    }
    this.updateActions()
  }

  select(app) {
    // do nothing if unchanged
    if (this.selected === app) return
    // deselect existing
    if (this.selected && this.selected !== app) {
      if (!this.selected.dead && this.selected.data.mover === this.world.network.id) {
        const app = this.selected
        app.data.mover = null
        app.data.position = app.root.position.toArray()
        app.data.quaternion = app.root.quaternion.toArray()
        app.data.scale = app.root.scale.toArray()
        app.data.state = {}
        this.world.network.send('entityModified', {
          id: app.data.id,
          mover: null,
          position: app.data.position,
          quaternion: app.data.quaternion,
          scale: app.data.scale,
          state: app.data.state,
        })
        app.build()
      }
      this.selected = null
      if (this.mode === 'grab') {
        this.control.keyC.capture = false
        this.control.scrollDelta.capture = false
      }
      if (this.mode === 'translate' || this.mode === 'rotate' || this.mode === 'scale') {
        this.detachGizmo()
      }
    }
    // select new (if any)
    if (app) {
      this.addUndo({
        name: 'move-entity',
        entityId: app.data.id,
        position: app.data.position.slice(),
        quaternion: app.data.quaternion.slice(),
        scale: app.data.scale.slice(),
      })
      if (app.data.mover !== this.world.network.id) {
        app.data.mover = this.world.network.id
        app.build()
        this.world.network.send('entityModified', { id: app.data.id, mover: app.data.mover })
      }
      this.selected = app
      if (this.mode === 'grab') {
        this.control.keyC.capture = true
        this.control.scrollDelta.capture = true
        this.target.position.copy(app.root.position)
        this.target.quaternion.copy(app.root.quaternion)
        this.target.scale.copy(app.root.scale)
        this.target.limit = PROJECT_MAX
      }
      if (this.mode === 'translate' || this.mode === 'rotate' || this.mode === 'scale') {
        this.attachGizmo(app, this.mode)
      }
    }
    // update actions
    this.updateActions()
  }

  attachGizmo(app, mode) {
    if (this.gizmo) this.detachGizmo()
    // create gizmo
    this.gizmo = new TransformControls(this.world.camera, this.viewport)
    this.gizmo.setSize(0.7)
    this.gizmo.space = this.localSpace ? 'local' : 'world'
    this.gizmo._gizmo.helper.translate.scale.setScalar(0)
    this.gizmo._gizmo.helper.rotate.scale.setScalar(0)
    this.gizmo._gizmo.helper.scale.scale.setScalar(0)
    this.gizmo.addEventListener('mouseDown', () => {
      this.gizmoActive = true
    })
    this.gizmo.addEventListener('mouseUp', () => {
      this.gizmoActive = false
    })
    this.gizmoTarget = new THREE.Object3D()
    this.gizmoHelper = this.gizmo.getHelper()
    // initialize it
    this.gizmoTarget.position.copy(app.root.position)
    this.gizmoTarget.quaternion.copy(app.root.quaternion)
    this.gizmoTarget.scale.copy(app.root.scale)
    this.world.stage.scene.add(this.gizmoTarget)
    this.world.stage.scene.add(this.gizmoHelper)
    this.gizmo.rotationSnap = SNAP_DEGREES * DEG2RAD
    this.gizmo.attach(this.gizmoTarget)
    this.gizmo.mode = mode
  }

  detachGizmo() {
    if (!this.gizmo) return
    this.world.stage.scene.remove(this.gizmoTarget)
    this.world.stage.scene.remove(this.gizmoHelper)
    this.gizmo.detach()
    this.gizmo.disconnect()
    this.gizmo.dispose()
    this.gizmo = null
  }

  getEntityAtReticle() {
    const hits = this.world.stage.raycastReticle()
    let entity
    for (const hit of hits) {
      entity = hit.getEntity?.()
      if (entity) break
    }
    return entity
  }

  getEntityAtPointer() {
    const hits = this.world.stage.raycastPointer(this.control.pointer.position)
    let entity
    for (const hit of hits) {
      entity = hit.getEntity?.()
      if (entity) break
    }
    return entity
  }

  getHitAtReticle(ignoreEntity, ignorePlayers) {
    const hits = this.world.stage.raycastReticle()
    let hit
    for (const _hit of hits) {
      const entity = _hit.getEntity?.()
      if (entity === ignoreEntity || (entity?.isPlayer && ignorePlayers)) continue
      hit = _hit
      break
    }
    return hit
  }

  onDragOver = e => {
    e.preventDefault()
  }

  onDragEnter = e => {
    this.dropTarget = e.target
    this.dropping = true
    this.file = null
  }

  onDragLeave = e => {
    if (e.target === this.dropTarget) {
      this.dropping = false
    }
  }

  onDrop = async e => {
    e.preventDefault()
    this.dropping = false
    // extract file from drop
    let file
    if (e.dataTransfer.items && e.dataTransfer.items.length > 0) {
      const item = e.dataTransfer.items[0]
      if (item.kind === 'file') {
        file = item.getAsFile()
      }
      // Handle multiple MIME types for URLs
      if (item.type === 'text/uri-list' || item.type === 'text/plain' || item.type === 'text/html') {
        const text = await getAsString(item)
        // Extract URL from the text (especially important for text/html type)
        const url = text.trim().split('\n')[0] // Take first line in case of multiple
        if (url.startsWith('http')) {
          // Basic URL validation
          const resp = await fetch(url)
          const blob = await resp.blob()
          file = new File([blob], new URL(url).pathname.split('/').pop(), { type: resp.headers.get('content-type') })
        }
      }
    } else if (e.dataTransfer.files && e.dataTransfer.files.length > 0) {
      file = e.dataTransfer.files[0]
    }
    if (!file) return
    // slight delay to ensure we get updated pointer position from window focus
    await new Promise(resolve => setTimeout(resolve, 100))
    // get file type
    const ext = file.name.split('.').pop().toLowerCase()
    // if vrm and we are not a builder and custom avatars are not allowed, stop here
    if (ext === 'vrm' && !this.canBuild() && !this.world.settings.customAvatars) {
      return
    }
    // check file size
    const maxSize = this.world.network.maxUploadSize * 1024 * 1024
    if (file.size > maxSize) {
      this.world.chat.add({
        id: uuid(),
        from: null,
        fromId: null,
        body: `File size too large (>${this.world.network.maxUploadSize}mb)`,
        createdAt: moment().toISOString(),
      })
      console.error(`File too large. Maximum size is ${maxSize / (1024 * 1024)}MB`)
      return
    }
    // builder rank required for non-vrm files
    if (ext !== 'vrm') {
      if (!this.canBuild()) {
        this.world.chat.add({
          id: uuid(),
          from: null,
          fromId: null,
          body: `You don't have permission to do that.`,
          createdAt: moment().toISOString(),
        })
        return
      }
      // switch to build mode
      this.toggle(true)
    }
    const transform = this.getSpawnTransform()
    if (ext === 'hyp') {
      this.addApp(file, transform)
    }
    if (ext === 'glb') {
      this.addModel(file, transform)
    }
    if (ext === 'vrm') {
      const canPlace = this.canBuild()
      this.addAvatar(file, transform, canPlace)
    }
  }

  async addApp(file, transform) {
    const info = await importApp(file)
    for (const asset of info.assets) {
      this.world.loader.insert(asset.type, asset.url, asset.file)
    }
    // if scene, update existing scene
    if (info.blueprint.scene) {
      const confirmed = await this.world.ui.confirm({
        title: 'Scene',
        message: 'Do you want to replace your current scene with this one?',
        confirmText: 'Replace',
        cancelText: 'Cancel',
      })
      if (!confirmed) return
      // modify blueprint optimistically
      const blueprint = this.world.blueprints.getScene()
      const change = {
        id: blueprint.id,
        version: blueprint.version + 1,
        name: info.blueprint.name,
        image: info.blueprint.image,
        author: info.blueprint.author,
        url: info.blueprint.url,
        desc: info.blueprint.desc,
        model: info.blueprint.model,
        script: info.blueprint.script,
        props: info.blueprint.props,
        preload: info.blueprint.preload,
        public: info.blueprint.public,
        locked: info.blueprint.locked,
        frozen: info.blueprint.frozen,
        unique: info.blueprint.unique,
        scene: info.blueprint.scene,
        disabled: info.blueprint.disabled,
      }
      this.world.blueprints.modify(change)
      // upload assets
      const promises = info.assets.map(asset => {
        return this.world.network.upload(asset.file)
      })
      await Promise.all(promises)
      // publish blueprint change for all
      this.world.network.send('blueprintModified', change)
      return
    }
    // otherwise spawn the app
    const blueprint = {
      id: uuid(),
      version: 0,
      name: info.blueprint.name,
      image: info.blueprint.image,
      author: info.blueprint.author,
      url: info.blueprint.url,
      desc: info.blueprint.desc,
      model: info.blueprint.model,
      script: info.blueprint.script,
      props: info.blueprint.props,
      preload: info.blueprint.preload,
      public: info.blueprint.public,
      locked: info.blueprint.locked,
      frozen: info.blueprint.frozen,
      unique: info.blueprint.unique,
      scene: info.blueprint.scene,
      disabled: info.blueprint.disabled,
    }
    const data = {
      id: uuid(),
      type: 'app',
      blueprint: blueprint.id,
      position: transform.position,
      quaternion: transform.quaternion,
      scale: [1, 1, 1],
      mover: null,
      uploader: this.world.network.id,
      pinned: false,
      state: {},
    }
    this.world.blueprints.add(blueprint, true)
    const app = this.world.entities.add(data, true)
    const promises = info.assets.map(asset => {
      return this.world.network.upload(asset.file)
    })
    try {
      await Promise.all(promises)
      app.onUploaded()
    } catch (err) {
      console.error('failed to upload .hyp assets')
      console.error(err)
      app.destroy()
    }
  }

  async addModel(file, transform) {
    // immutable hash the file
    const hash = await hashFile(file)
    // use hash as glb filename
    const filename = `${hash}.glb`
    // canonical url to this file
    const url = `asset://${filename}`
    // cache file locally so this client can insta-load it
    this.world.loader.insert('model', url, file)
    // make blueprint
    const blueprint = {
      id: uuid(),
      version: 0,
      name: file.name.split('.')[0],
      image: null,
      author: null,
      url: null,
      desc: null,
      model: url,
      script: null,
      props: {},
      preload: false,
      public: false,
      locked: false,
      unique: false,
      scene: false,
      disabled: false,
    }
    // register blueprint
    this.world.blueprints.add(blueprint, true)
    // spawn the app moving
    // - mover: follows this clients cursor until placed
    // - uploader: other clients see a loading indicator until its fully uploaded
    const data = {
      id: uuid(),
      type: 'app',
      blueprint: blueprint.id,
      position: transform.position,
      quaternion: transform.quaternion,
      scale: [1, 1, 1],
      mover: null,
      uploader: this.world.network.id,
      pinned: false,
      state: {},
    }
    const app = this.world.entities.add(data, true)
    // upload the glb
    await this.world.network.upload(file)
    // mark as uploaded so other clients can load it in
    app.onUploaded()
  }

  async addAvatar(file, transform, canPlace) {
    // immutable hash the file
    const hash = await hashFile(file)
    // use hash as vrm filename
    const filename = `${hash}.vrm`
    // canonical url to this file
    const url = `asset://${filename}`
    // cache file locally so this client can insta-load it
    this.world.loader.insert('avatar', url, file)
    this.world.emit('avatar', {
      file,
      url,
      hash,
      canPlace,
      onPlace: async () => {
        // close pane
        this.world.emit('avatar', null)
        // make blueprint
        const blueprint = {
          id: uuid(),
          version: 0,
          name: file.name,
          image: null,
          author: null,
          url: null,
          desc: null,
          model: url,
          script: null,
          props: {},
          preload: false,
          public: false,
          locked: false,
          unique: false,
          scene: false,
          disabled: false,
        }
        // register blueprint
        this.world.blueprints.add(blueprint, true)
        // spawn the app moving
        // - mover: follows this clients cursor until placed
        // - uploader: other clients see a loading indicator until its fully uploaded
        const data = {
          id: uuid(),
          type: 'app',
          blueprint: blueprint.id,
          position: transform.position,
          quaternion: transform.quaternion,
          scale: [1, 1, 1],
          mover: null,
          uploader: this.world.network.id,
          pinned: false,
          state: {},
        }
        const app = this.world.entities.add(data, true)
        // upload the glb
        await this.world.network.upload(file)
        // mark as uploaded so other clients can load it in
        app.onUploaded()
      },
      onEquip: async () => {
        // close pane
        this.world.emit('avatar', null)
        // prep new user data
        const player = this.world.entities.player
        const prevUrl = player.data.avatar
        // update locally
        player.modify({ avatar: url, sessionAvatar: null })
        // upload
        try {
          await this.world.network.upload(file)
        } catch (err) {
          console.error(err)
          // revert
          player.modify({ avatar: prevUrl })
          return
        }
        if (player.data.avatar !== url) {
          return // player equipped a new vrm while this one was uploading >.>
        }
        // update for everyone
        this.world.network.send('entityModified', {
          id: player.data.id,
          avatar: url,
        })
      },
    })
  }

  getSpawnTransform(atReticle) {
    const hit = atReticle
      ? this.world.stage.raycastReticle()[0]
      : this.world.stage.raycastPointer(this.control.pointer.position)[0]
    const position = hit ? hit.point.toArray() : [0, 0, 0]
    let quaternion
    if (hit) {
      e1.copy(this.world.rig.rotation).reorder('YXZ')
      e1.x = 0
      e1.z = 0
      const degrees = e1.y * RAD2DEG
      const snappedDegrees = Math.round(degrees / SNAP_DEGREES) * SNAP_DEGREES
      e1.y = snappedDegrees * DEG2RAD
      q1.setFromEuler(e1)
      quaternion = q1.toArray()
    } else {
      quaternion = [0, 0, 0, 1]
    }
    return { position, quaternion }
  }

  destroy() {
    this.viewport.removeEventListener('dragover', this.onDragOver)
    this.viewport.removeEventListener('dragenter', this.onDragEnter)
    this.viewport.removeEventListener('dragleave', this.onDragLeave)
    this.viewport.removeEventListener('drop', this.onDrop)
  }
}

function getAsString(item) {
  return new Promise(resolve => {
    item.getAsString(resolve)
  })
}

import { isNumber } from 'lodash-es'
import { System } from './System'
import { Raycaster, Vector2 } from 'three'

/**
 * Client Camera Controls System
 *
 * Provides programmatic control over camera settings including:
 * - Depth of Field (DOF) settings
 * - Focal length
 * - Helper visibility
 */
export class ClientCameraControls extends System {
  constructor(world) {
    super(world)
    this.raycaster = new Raycaster()
    this.raycaster.near = 0.1
    this.raycaster.far = 1000
    this.screenCenter = new Vector2(0, 0) // Center of screen

    // Master control
    this.enabled = true // Camera controls ON by default for ADS to work

    // Autofocus state
    this.reticleAutofocus = false
    this.playerAutofocus = false
    this.focusSmoothing = true
    this.focusSpeed = 0.1
    this.targetFocusDistance = 10
    this.currentFocusDistance = 10
    this.reticleFocusTimer = 0
    this.reticleFocusDelay = 0.5 // seconds before focusing
    this.lastReticleTarget = null

    // Zoom control
    this.zoomSpeed = 5
    this.enableScrollZoom = false // Off by default

    // Dynamic DOF compensation
    this.dynamicDOF = false // Auto-adjust DOF based on zoom
    this.lastCameraZoom = null
    this.debugDOF = false // Debug logging

    // ADS-style zoom
    this.adsZoomEnabled = true // Enable ADS by default
    this.isAiming = false
    this.baseFocalLength = 24 // Will be set properly in init()
    this.adsZoomFocalLength = 85 // Zoomed in focal length
    this.currentFocalLength = 24
    this.targetFocalLength = 24
    this.zoomTransitionSpeed = 0.3
    this.adsBokehMultiplier = 2.5 // Increase bokeh when zoomed
    this.normalBokehScale = 1

    // How strongly focus distance grows with camera zoom-out (legacy scalar)
    this.zoomDistanceMultiplier = 3
    this.anchorFocusToPlayer = true
    // Blend player distance with stop-based focus as we zoom out (0..1)
    this.playerFocusBlendMax = 0.15
    this.playerFocusBlendPow = 1.2

    // Track observed zoom range so we can normalize stops to user's device
    // Seed with a sensible span so defaults work without manual calibration
    this.zoomObservedMin = 0
    this.zoomObservedMax = 12

    // Four-stop profile across normalized zoom t in [0..1]
    this.zoomStopsNormalized = true
    this.zoomStops = [
      { t: 0.0, focus: 6, range: 2.0, bokeh: 1.0 },
      { t: 0.318, focus: 30, range: 80.0, bokeh: 0.5 },
      { t: 0.618, focus: 60, range: 160.0, bokeh: 0.4 },
      { t: 1.0, focus: 120, range: 240.0, bokeh: 0.35 },
    ]

    // Focus range shaping (shallow when close, deeper when far)
    this.focusRangeCloseFactor = 0.25
    this.focusRangeFarFactor = 3.0

    // One-click autofocus using right mouse (outside build mode)
    this.rightClickAutofocus = true
  }

  init() {
    console.log('ClientCameraControls: Initializing with default settings')

    // Use the exact same settings as the reset command
    // These are the defaults that make the camera look correct
    this.baseFocalLength = 24 // Wide landscape preset
    this.adsZoomFocalLength = 85 // Zoomed in focal length for ADS
    this.currentFocalLength = 24
    this.targetFocalLength = 24

    // Set all the defaults
    this.enabled = true // Enable camera controls
    this.adsZoomEnabled = true // Enable ADS by default
    this.isAiming = false
    this.normalBokehScale = 1

    // Autofocus defaults
    this.reticleAutofocus = false
    this.playerAutofocus = false
    this.focusSmoothing = true
    this.focusSpeed = 0.1
    this.reticleFocusDelay = 0.5

    // Other defaults
    this.enableScrollZoom = false
    this.zoomSpeed = 5
    this.currentFocusDistance = 10
    this.targetFocusDistance = 10

    // Apply settings to prefs
    if (this.world.prefs) {
      this.world.prefs.setFocalLength(24)
      this.world.prefs.setDOFBokehScale(1)
      this.world.prefs.setDOFFocusDistance(10)
      this.world.prefs.setDOFFocusRange(5)
      this.world.prefs.setDOFEnabled(true)
      this.world.prefs.setFocusSmoothing(false)

      // Apply the focal length
      this.applyFocalLength(24)
    }

    // Bind controls for mouse input
    if (this.world.controls) {
      this.control = this.world.controls.bind({
        priority: 1000, // High priority to capture mouse
      })
    }

    // Set up admin console commands if in browser
    if (typeof window !== 'undefined') {
      this.setupConsoleCommands()
    }
  }

  start() {
    // Listen for pref changes
    this.world.prefs.on('change', this.onPrefsChange)

    // Enable dynamic DOF when using the default/player camera
    this.world.on('camera-changed', cameraNode => {
      const isPlayerCam = !!cameraNode?.isPlayerCamera
      this.dynamicDOF = isPlayerCam || this.dynamicDOF
      if (isPlayerCam && this.world.prefs.dofEnabled) {
        // Seed focus immediately based on current zoom level
        const z = Math.abs(this.world.camera?.position?.z || 0)
        const baseFocus = 5 + z * 1.5
        this.targetFocusDistance = baseFocus
        this.currentFocusDistance = baseFocus
        this.setDOFFocusDistance(baseFocus)
      }
    })

    // Initialize dynamic DOF state based on current camera
    const currentCam = this.world.cameraManager?.activeCamera || this.world.defaultCameraNode
    this.dynamicDOF = !!currentCam?.isPlayerCamera
  }

  resetCamera() {
    // Reset focal length to base
    this.baseFocalLength = 24
    this.adsZoomFocalLength = 85
    this.currentFocalLength = this.baseFocalLength
    this.targetFocalLength = this.baseFocalLength

    // Reset DOF settings
    this.normalBokehScale = 1
    if (this.world.prefs) {
      this.world.prefs.setFocalLength(this.baseFocalLength)
      this.world.prefs.setDOFBokehScale(this.normalBokehScale)
    }

    // Reset ADS state
    this.isAiming = false

    // Reset control states
    if (this.control?.mouseRight) {
      this.control.mouseRight.capture = false
    }
  }

  destroy() {
    this.world.prefs.off('change', this.onPrefsChange)
    this.control?.release()
    this.control = null
  }

  onPrefsChange = changes => {
    if (changes.reticleAutofocus) this.reticleAutofocus = changes.reticleAutofocus.value
    if (changes.playerAutofocus) this.playerAutofocus = changes.playerAutofocus.value
    if (changes.focusSmoothing) this.focusSmoothing = changes.focusSmoothing.value
    if (changes.focusSpeed) this.focusSpeed = changes.focusSpeed.value
    if (changes.reticleFocusDelay) this.reticleFocusDelay = changes.reticleFocusDelay.value
    if (changes.scrollZoomEnabled) this.enableScrollZoom = changes.scrollZoomEnabled.value
    if (changes.zoomSpeed) this.zoomSpeed = changes.zoomSpeed.value
  }

  update(delta) {
    // Handle ADS-style zoom (right mouse button)
    // Disable ADS if in build mode since right-click is used for building
    const inBuildMode = this.world.builder?.enabled === true

    // If we were aiming but entered build mode, stop aiming immediately
    if (inBuildMode && this.isAiming) {
      this.isAiming = false
      this.targetFocalLength = this.baseFocalLength
      this.world.prefs.setDOFBokehScale(this.normalBokehScale)
      if (this.control?.mouseRight?.capture !== undefined) {
        this.control.mouseRight.capture = false
      }
      if (this.debugDOF) {
        console.log('ADS: Disabled due to build mode')
      }
    }

    // Right-click autofocus (when not in build mode)
    if (this.enabled && this.rightClickAutofocus && this.control && !inBuildMode) {
      const rightPressed = this.control?.mouseRight?.pressed === true
      if (rightPressed) {
        // Capture to avoid context menu
        if (this.control.mouseRight.capture !== undefined) this.control.mouseRight.capture = true
        const distance = this.raycastFocusDistance() || this.getFocusDistanceToPlayer() || 10
        this.targetFocusDistance = distance
        // Snap focus faster for explicit autofocus
        this.currentFocusDistance = distance
        this.setDOFFocusDistance(distance)
        if (this.debugDOF) console.log(`Right-click autofocus: ${distance.toFixed(2)}`)
      }
    }

    // Only process ADS if not in build mode
    if (this.enabled && this.adsZoomEnabled && this.control && !inBuildMode) {
      // Check if right mouse button is currently down (not pressed/released)
      // Make sure it's explicitly true, not undefined or truthy
      const rightMouseDown = this.control?.mouseRight?.down === true

      // Check if aiming state changed
      if (rightMouseDown && !this.isAiming) {
        // Start aiming
        this.isAiming = true
        this.targetFocalLength = this.adsZoomFocalLength

        // Save current bokeh and enhance it
        this.normalBokehScale = this.world.prefs.dofBokehScale || 1
        this.world.prefs.setDOFBokehScale(this.normalBokehScale * this.adsBokehMultiplier)

        // Do not auto-enable DOF; leave to user preference

        // Capture right mouse to prevent context menu
        if (this.control.mouseRight.capture !== undefined) {
          this.control.mouseRight.capture = true
        }

        if (this.debugDOF) {
          console.log('ADS: Zooming in')
        }
      } else if (!rightMouseDown && this.isAiming) {
        // Stop aiming
        this.isAiming = false
        this.targetFocalLength = this.baseFocalLength

        // Restore normal bokeh
        this.world.prefs.setDOFBokehScale(this.normalBokehScale)

        // Release capture
        if (this.control.mouseRight.capture !== undefined) {
          this.control.mouseRight.capture = false
        }

        if (this.debugDOF) {
          console.log('ADS: Zooming out')
        }
      }
    }

    // Smooth focal length transition (only if not in build mode or if zooming out)
    if (!inBuildMode || this.targetFocalLength === this.baseFocalLength) {
      if (Math.abs(this.targetFocalLength - this.currentFocalLength) > 0.1) {
        this.currentFocalLength += (this.targetFocalLength - this.currentFocalLength) * this.zoomTransitionSpeed
        this.setFocalLength(this.currentFocalLength)
      } else if (this.currentFocalLength !== this.targetFocalLength) {
        // Snap to target if very close
        this.currentFocalLength = this.targetFocalLength
        this.setFocalLength(this.currentFocalLength)
      }
    }

    // Removed scroll zoom to avoid conflicting with native camera controls
    // Use ADS zoom (right-click) instead for focal length adjustment

    // Only run DOF updates if master control is enabled AND DOF is enabled
    if (!this.enabled || !this.world.prefs.dofEnabled) return

    // Dynamic DOF compensation based on camera zoom (mouse scroll distance)
    if (this.dynamicDOF && this.world.camera) {
      // Calculate focus based on camera distance from player (zoom level)
      // In first person (z=0), focus close. In third person, focus further
      const cameraZoom = Math.abs(this.world.camera.position.z)
      const camFar = this.world.camera.far || 1200

      // Track zoom change to react instantly when user scroll-zooms
      const prevZoom = this.lastCameraZoom
      const zoomDelta = prevZoom == null ? 0 : Math.abs(cameraZoom - prevZoom)
      this.lastCameraZoom = cameraZoom

      // Update observed zoom range
      this.zoomObservedMin = this.zoomObservedMin === null ? cameraZoom : Math.min(this.zoomObservedMin, cameraZoom)
      this.zoomObservedMax = this.zoomObservedMax === null ? cameraZoom : Math.max(this.zoomObservedMax, cameraZoom)
      const zoomSpan = Math.max(1e-6, this.zoomObservedMax - this.zoomObservedMin)
      const tZoom = Math.min(1, Math.max(0, (cameraZoom - this.zoomObservedMin) / zoomSpan))

      // Evaluate four-stop zoom profile (piecewise linear) in normalized space
      const stops =
        this.zoomStops && this.zoomStops.length >= 2
          ? this.zoomStops
          : [
              { t: 0, focus: 3, range: 1.0, bokeh: 1.0 },
              { t: 1, focus: Math.min(60, camFar * 0.5), range: Math.min(18, camFar * 0.4), bokeh: 0.5 },
            ]
      let s0 = stops[0]
      let s1 = stops[stops.length - 1]
      for (let i = 0; i < stops.length - 1; i++) {
        const a = stops[i]
        const b = stops[i + 1]
        if (tZoom >= a.t && tZoom <= b.t) {
          s0 = a
          s1 = b
          break
        }
        if (tZoom < stops[0].t) {
          s0 = stops[0]
          s1 = stops[1]
          break
        }
        if (tZoom > stops[stops.length - 2].t) {
          s0 = stops[stops.length - 2]
          s1 = stops[stops.length - 1]
        }
      }
      const denom = Math.max(1e-6, s1.t - s0.t)
      const t = Math.min(1, Math.max(0, (tZoom - s0.t) / denom))
      const lerp = (a, b, u) => a + (b - a) * u
      const baseFocus = Math.min(camFar * 0.5, lerp(s0.focus, s1.focus, t))
      const baseRange = Math.min(camFar * 0.45, lerp(s0.range, s1.range, t))
      const baseBokeh = Math.max(0.2, Math.min(2.0, lerp(s0.bokeh, s1.bokeh, t)))

      // Choose focus center
      let playerDist = this.getFocusDistanceToPlayer()
      if (this.anchorFocusToPlayer && playerDist !== null && isFinite(playerDist)) {
        // Blend between player distance and stop-based focus according to zoom
        const blend = Math.max(0, Math.min(1, Math.pow(tZoom, this.playerFocusBlendPow) * this.playerFocusBlendMax))
        this.targetFocusDistance = playerDist * (1 - blend) + baseFocus * blend
      } else {
        // Blend with reticle raycast if available (low influence to avoid jumpiness)
        let raycastDistance = this.raycastFocusDistance()
        if (raycastDistance !== null && isFinite(raycastDistance) && raycastDistance > 0.5) {
          this.targetFocusDistance = raycastDistance * 0.25 + baseFocus * 0.75
        } else {
          this.targetFocusDistance = baseFocus
        }
      }

      // Apply shaped focus range and bokeh
      let rangeUsed = baseRange
      // Ensure the player's plane remains within focus range if we blended away
      if (playerDist !== null && isFinite(playerDist)) {
        const extra = Math.abs(this.targetFocusDistance - playerDist) * 1.25
        if (extra > rangeUsed) rangeUsed = Math.min(camFar * 0.45, extra)
      }
      this.world.prefs.setDOFFocusRange(rangeUsed)
      this.world.prefs.setDOFBokehScale(baseBokeh)

      if (this.debugDOF) {
        console.log(
          `DOF: Focus=${this.targetFocusDistance.toFixed(2)} Range=${rangeUsed.toFixed(2)} Zoom=${cameraZoom.toFixed(2)} tZoom=${tZoom.toFixed(2)} segT=${t.toFixed(2)} anchor=${this.anchorFocusToPlayer}`
        )
      }

      // When the user changes zoom, snap focus to prevent temporary blur
      if (zoomDelta > 0.05) {
        this.currentFocusDistance = this.targetFocusDistance
        this.setDOFFocusDistance(this.currentFocusDistance)
      }
    }

    // Smooth focus transition
    if (this.focusSmoothing && Math.abs(this.targetFocusDistance - this.currentFocusDistance) > 0.01) {
      this.currentFocusDistance += (this.targetFocusDistance - this.currentFocusDistance) * this.focusSpeed
      this.setDOFFocusDistance(this.currentFocusDistance)
    } else if (!this.focusSmoothing && this.targetFocusDistance !== this.currentFocusDistance) {
      this.currentFocusDistance = this.targetFocusDistance
      this.setDOFFocusDistance(this.currentFocusDistance)
    }

    // Reticle autofocus (use head raycast for consistency)
    if (this.reticleAutofocus && !this.dynamicDOF) {
      const raycastDist = this.raycastFromPlayerHead() || this.raycastFocusDistance()

      if (raycastDist !== null) {
        // Check if we're looking at a new target
        if (Math.abs(raycastDist - (this.lastReticleTarget || 0)) > 0.5) {
          // New target, reset timer
          this.reticleFocusTimer = 0
          this.lastReticleTarget = raycastDist
        } else {
          // Same target, increment timer
          this.reticleFocusTimer += delta

          // After delay, start focusing
          if (this.reticleFocusTimer >= this.reticleFocusDelay) {
            this.targetFocusDistance = raycastDist
          }
        }
      }
    }

    // Player autofocus (overrides reticle if both are enabled)
    if (this.playerAutofocus && !this.dynamicDOF) {
      const distance = this.getFocusDistanceToPlayer()
      if (distance !== null) {
        this.targetFocusDistance = distance
      }
    }
  }

  // Depth of Field Controls
  enableDOF() {
    this.world.prefs.setDOFEnabled(true)
  }

  disableDOF() {
    this.world.prefs.setDOFEnabled(false)
  }

  setDOFFocusDistance(distance) {
    if (!isNumber(distance) || distance < 0) {
      console.warn('DOF focus distance must be a positive number')
      return
    }
    this.world.prefs.setDOFFocusDistance(distance)
  }

  setDOFFocusRange(range) {
    if (!isNumber(range) || range < 0) {
      console.warn('DOF focus range must be a positive number')
      return
    }
    this.world.prefs.setDOFFocusRange(range)
  }

  setDOFBokehScale(scale) {
    if (!isNumber(scale) || scale < 0) {
      console.warn('DOF bokeh scale must be a positive number')
      return
    }
    this.world.prefs.setDOFBokehScale(scale)
  }

  // Focal Length Control
  setFocalLength(focalLength) {
    if (!isNumber(focalLength) || focalLength < 1 || focalLength > 200) {
      console.warn('Focal length must be a number between 1 and 200')
      return
    }
    this.world.prefs.setFocalLength(focalLength)
    this.applyFocalLength(focalLength)
  }

  applyFocalLength(focalLength) {
    if (this.world.camera) {
      // Convert focal length to FOV
      // Using standard 35mm film equivalent calculation
      const sensorHeight = 24 // 35mm sensor height in mm
      const fov = 2 * Math.atan(sensorHeight / (2 * focalLength)) * (180 / Math.PI)
      this.world.camera.fov = fov

      // Dynamically adjust far plane based on focal length to optimize performance
      // Wide angle (low focal length) = see far, Telephoto (high focal length) = see less far
      const baseFar = 1200 // Default far plane
      let dynamicFar

      if (focalLength <= 50) {
        // Wide to normal: full range
        dynamicFar = baseFar
      } else if (focalLength <= 85) {
        // Portrait range: slight reduction
        dynamicFar = baseFar * 0.95 // 1140 - keep skybox visible
      } else if (focalLength <= 135) {
        // Telephoto: moderate reduction
        dynamicFar = baseFar * 0.85 // 1020 - still see skybox
      } else {
        // Super telephoto: more reduction but keep skybox
        dynamicFar = baseFar * 0.75 // 900 - minimum for skybox
      }

      this.world.camera.far = dynamicFar
      this.world.camera.updateProjectionMatrix()

      if (this.debugDOF) {
        console.log(`Focal length: ${focalLength}mm, FOV: ${fov.toFixed(1)}°, Far: ${dynamicFar}`)
      }
    }
  }

  getFocalLength() {
    return this.world.prefs.focalLength
  }

  // Helper Controls
  showHelpers() {
    this.world.prefs.setShowHelpers(true)
  }

  hideHelpers() {
    this.world.prefs.setShowHelpers(false)
  }

  toggleHelpers() {
    this.world.prefs.setShowHelpers(!this.world.prefs.showHelpers)
  }

  // Get current settings
  getCameraSettings() {
    return {
      dof: {
        enabled: this.world.prefs.dofEnabled,
        focusDistance: this.world.prefs.dofFocusDistance,
        focusRange: this.world.prefs.dofFocusRange,
        bokehScale: this.world.prefs.dofBokehScale,
      },
      focalLength: this.world.prefs.focalLength,
      fov: this.world.camera.fov,
      showHelpers: this.world.prefs.showHelpers,
    }
  }

  // Auto-focus on target position
  autoFocus(targetPosition) {
    if (!targetPosition) {
      console.warn('Target position required for auto-focus')
      return
    }

    const distance = this.world.camera.position.distanceTo(targetPosition)
    this.setDOFFocusDistance(distance)
  }

  // Raycast from camera center to get focus distance
  raycastFocusDistance() {
    if (!this.world.camera || !this.world.stage) {
      if (this.debugDOF) {
        console.log('DOF Debug: Camera or stage not ready')
      }
      return null
    }

    // Check if viewport is ready (required for raycast)
    if (!this.world.stage.viewport) {
      if (this.debugDOF) {
        console.log('DOF Debug: Stage viewport not ready')
      }
      return null
    }

    // Use Stage raycast which properly uses the octree
    try {
      const hits = this.world.stage.raycastReticle()
      if (hits && hits.length > 0) {
        // Filter out very close hits (likely the player)
        const validHits = hits.filter(hit => hit.distance > 0.5)
        if (validHits.length > 0) {
          const distance = validHits[0].distance
          if (this.debugDOF) {
            console.log(
              `DOF Debug: Raycast hit at distance ${distance.toFixed(2)}, object:`,
              validHits[0].object?.name || 'unknown'
            )
          }
          return distance
        } else if (this.debugDOF) {
          console.log('DOF Debug: All hits were too close (< 0.5)')
        }
      } else if (this.debugDOF) {
        console.log('DOF Debug: No octree hits')
      }
    } catch (err) {
      if (this.debugDOF) {
        console.log('DOF Debug: Stage raycast error:', err.message)
      }
    }

    // No fallback to manual scene traversal since objects are in the octree
    return null
  }

  // Auto-focus using raycast
  autoFocusRaycast() {
    const distance = this.raycastFocusDistance()
    if (distance !== null) {
      this.setDOFFocusDistance(distance)
      return distance
    }
    return null
  }

  // Get focus distance to player
  getFocusDistanceToPlayer() {
    if (!this.world.entities?.player || !this.world.camera) {
      return null
    }

    const player = this.world.entities.player

    // Try to get player head position for more accurate focus
    let playerPos
    if (player.entity?.position) {
      playerPos = player.entity.position.clone()
      // Add approximate head height offset
      playerPos.y += 1.6 // Standard eye height offset
    } else {
      return null
    }

    // Get actual camera world position (accounting for rig)
    const cameraWorldPos = new THREE.Vector3()
    this.world.camera.getWorldPosition(cameraWorldPos)

    // Calculate distance from camera to player head
    return cameraWorldPos.distanceTo(playerPos)
  }

  // Raycast from player head position towards camera look direction
  raycastFromPlayerHead() {
    if (!this.world.entities?.player || !this.world.camera || !this.world.scene) {
      return null
    }

    const player = this.world.entities.player
    if (!player.entity?.position) return null

    // Get player head position
    const headPos = player.entity.position.clone()
    headPos.y += 1.6 // Standard eye height

    // Get camera direction
    const cameraDir = new THREE.Vector3()
    this.world.camera.getWorldDirection(cameraDir)

    // Set up raycaster from player head in camera direction
    this.raycaster.set(headPos, cameraDir)

    // Get all meshes in the scene
    const intersectables = []
    this.world.scene.traverse(object => {
      if (object.isMesh && object.visible && object !== player.entity) {
        intersectables.push(object)
      }
    })

    // Perform raycast
    const intersects = this.raycaster.intersectObjects(intersectables, false)

    if (intersects.length > 0) {
      // Return distance from camera to intersection
      const cameraWorldPos = new THREE.Vector3()
      this.world.camera.getWorldPosition(cameraWorldPos)
      return cameraWorldPos.distanceTo(intersects[0].point)
    }

    return null
  }

  // Auto-focus on player
  autoFocusPlayer() {
    const distance = this.getFocusDistanceToPlayer()
    if (distance !== null) {
      this.setDOFFocusDistance(distance)
      return distance
    }
    return null
  }

  // Master enable/disable
  enable() {
    this.enabled = true
    console.log('Camera controls system: ENABLED')
  }

  disable() {
    this.enabled = false
    // Reset autofocus when disabling
    this.reticleAutofocus = false
    this.playerAutofocus = false
    this.enableScrollZoom = false
    console.log('Camera controls system: DISABLED')
  }

  setEnabled(enabled) {
    if (enabled) {
      this.enable()
    } else {
      this.disable()
    }
  }

  // Enable/disable autofocus modes
  setReticleAutofocus(enabled) {
    this.reticleAutofocus = enabled
    this.world.prefs.setReticleAutofocus(enabled)
    if (!enabled) {
      this.reticleFocusTimer = 0
      this.lastReticleTarget = null
    }
  }

  setPlayerAutofocus(enabled) {
    this.playerAutofocus = enabled
    this.world.prefs.setPlayerAutofocus(enabled)
  }

  setFocusSmoothing(enabled) {
    this.focusSmoothing = enabled
    this.world.prefs.setFocusSmoothing(enabled)
  }

  setFocusSpeed(speed) {
    this.focusSpeed = Math.max(0.01, Math.min(1, speed))
    this.world.prefs.setFocusSpeed(this.focusSpeed)
  }

  setReticleFocusDelay(delay) {
    this.reticleFocusDelay = Math.max(0, delay)
    this.world.prefs.setReticleFocusDelay(this.reticleFocusDelay)
  }

  // Zoom control
  setZoomSpeed(speed) {
    this.zoomSpeed = Math.max(1, Math.min(50, speed))
    this.world.prefs.setZoomSpeed(this.zoomSpeed)
  }

  setScrollZoomEnabled(enabled) {
    this.enableScrollZoom = enabled
    this.world.prefs.setScrollZoomEnabled(enabled)
  }

  // Handle scroll wheel zoom (focal length only, not camera distance)
  handleScrollZoom(delta) {
    if (!this.enableScrollZoom) return

    // Only adjust focal length, let Hyperfy handle camera distance
    const currentFocalLength = this.world.prefs.focalLength || 50
    const change = -delta * this.zoomSpeed
    const newFocalLength = Math.max(10, Math.min(200, currentFocalLength + change))

    this.setFocalLength(newFocalLength)

    if (this.debugDOF) {
      console.log(`Focal length zoom: ${newFocalLength.toFixed(0)}mm`)
    }
  }

  // Preset camera settings
  applyPreset(presetName) {
    const presets = {
      portrait: {
        focalLength: 85,
        dofEnabled: true,
        dofFocusDistance: 5,
        dofFocusRange: 2,
        dofBokehScale: 1.5,
      },
      landscape: {
        focalLength: 24,
        dofEnabled: false,
        dofFocusDistance: 20,
        dofFocusRange: 10,
        dofBokehScale: 0.5,
      },
      macro: {
        focalLength: 100,
        dofEnabled: true,
        dofFocusDistance: 1,
        dofFocusRange: 0.5,
        dofBokehScale: 2,
      },
      standard: {
        focalLength: 50,
        dofEnabled: false,
        dofFocusDistance: 10,
        dofFocusRange: 5,
        dofBokehScale: 0.5,
      },
    }

    const preset = presets[presetName]
    if (!preset) {
      console.warn(`Unknown camera preset: ${presetName}. Available presets: ${Object.keys(presets).join(', ')}`)
      return
    }

    this.setFocalLength(preset.focalLength)
    this.world.prefs.setDOFEnabled(preset.dofEnabled)
    this.setDOFFocusDistance(preset.dofFocusDistance)
    this.setDOFFocusRange(preset.dofFocusRange)
    this.setDOFBokehScale(preset.dofBokehScale)
  }

  // Check if current player is admin
  isPlayerAdmin() {
    const player = this.world.entities?.player
    return player && player.isAdmin && player.isAdmin()
  }

  // Check if current player is builder
  isPlayerBuilder() {
    const player = this.world.entities?.player
    return player && player.isBuilder && player.isBuilder()
  }

  // Setup console commands for admins
  setupConsoleCommands() {
    window.cam = {
      // Enable/disable master control
      enable: () => {
        if (!this.isPlayerAdmin()) {
          console.warn('Camera controls are admin-only')
          return false
        }
        this.enable()
        return true
      },

      disable: () => {
        if (!this.isPlayerAdmin()) {
          console.warn('Camera controls are admin-only')
          return false
        }
        this.disable()
        return true
      },

      // DOF controls
