  }

  setDOFEnabled(value) {
    this.modify('dofEnabled', value)
  }

  setDOFFocusDistance(value) {
    this.modify('dofFocusDistance', value)
  }

  setDOFFocusRange(value) {
    this.modify('dofFocusRange', value)
  }

  setDOFBokehScale(value) {
