import { System } from './System'

import StatsGL from '../libs/stats-gl'
import Panel from '../libs/stats-gl/panel'
import { isBoolean } from 'lodash-es'

const PING_RATE = 1 / 2

/**
 * Stats System
 *
 * - runs on the client
 * - attaches stats to the ui to see fps/cpu/gpu
 *
 */
export class ClientStats extends System {
  constructor(world) {
    super(world)
    this.stats = null
    this.ui = null
    this.active = false
    this.lastPingAt = 0
    this.pingHistory = []
    this.pingHistorySize = 30 // Store the last 30 ping measurements
    this.maxPing = 0.01 // Starting value for max (will be updated)
  }

  init({ ui }) {
    this.ui = ui
  }

  start() {
    this.world.prefs.on('change', this.onPrefsChange)
    this.world.on('ui', this.onUIState)
    this.world.on('ready', this.onReady)
  }

  onReady = () => {
    if (this.world.prefs.stats) {
      this.toggle(true)
    }
  }

  toggle(value) {
    value = isBoolean(value) ? value : !this.active
    if (this.active === value) return
    this.active = value
    if (this.active) {
      if (!this.stats) {
        this.stats = new StatsGL({
          logsPerSecond: 20,
          samplesLog: 100,
          samplesGraph: 10,
          precision: 2,
          horizontal: true,
          minimal: false,
          mode: 0,
        })
        this.stats.dom.style.zIndex = null
        this.stats.init(this.world.graphics.renderer, false)
        this.ping = new Panel('PING', '#f00', '#200')
        this.stats.addPanel(this.ping, 3)
      }
      this.ui.appendChild(this.stats.dom)
    } else {
      this.ui.removeChild(this.stats.dom)
    }
  }

  preTick() {
    if (this.active) {
      this.stats.begin()
    }
  }

  update(delta) {
    if (!this.active) return
    this.lastPingAt += delta
    if (this.lastPingAt > PING_RATE) {
      const time = performance.now()
      this.world.network.send('ping', time)
      this.lastPingAt = 0
    }
  }

  postTick() {
    if (this.active) {
      this.stats.end()
      this.stats.update()
    }
  }

  onPong(time) {
    const rttMs = performance.now() - time
    if (this.active && this.ping) {
      this.pingHistory.push(rttMs)
      if (this.pingHistory.length > this.pingHistorySize) {
        this.pingHistory.shift()
      }
      let sum = 0
      let min = Infinity
      let max = 0
      for (let i = 0; i < this.pingHistory.length; i++) {
        const value = this.pingHistory[i]
        sum += value
        if (value < min) min = value
        if (value > max) max = value
      }
      const avg = sum / this.pingHistory.length
      if (max > this.maxPing) {
        this.maxPing = max
      }
      this.ping.update(
        avg, // current value (average)
        rttMs, // graph value (latest ping)
        max, // max value for text display
        this.maxPing, // max value for graph scaling
        0 // number of decimal places (0 for ping)
      )
    }
    // emit an event so other systems can use ping information
    // if (this.pingHistory.length > 0) {
    //   let sum = 0
    //   let min = Infinity
    //   let max = 0
    //   for (let i = 0; i < this.pingHistory.length; i++) {
    //     const value = this.pingHistory[i]
    //     sum += value
    //     if (value < min) min = value
    //     if (value > max) max = value
    //   }
    //   this.world.emit('ping-update', {
    //     current: rttMs,
    //     average: Math.round(sum / this.pingHistory.length),
    //     min: min,
    //     max: max,
    //   })
    // }
  }

  onPrefsChange = changes => {
    if (changes.stats) {
      this.toggle(changes.stats.value)
    }
  }

  onUIState = state => {
    if (this.active && !state.visible) {
      this.uiHidden = true
      this.toggle(false)
    } else if (this.uiHidden && state.visible) {
      this.uiHidden = null
      this.toggle(true)
    }
  }

  destroy() {
    this.toggle(false)
  }
}

import * as THREE from 'three'

import { System } from './System'

export class ClientTarget extends System {
  constructor(world) {
    super(world)
  }

  init({ ui }) {
    this.ui = ui
  }

  start() {
    this.guide = document.createElement('div')
    this.guide.style.position = 'absolute'
    this.guide.style.width = '30px'
    this.guide.style.height = '30px'
    this.guide.style.display = 'flex'
    this.guide.style.alignItems = 'center'
    this.guide.style.justifyContent = 'center'
    this.guide.style.transform = 'translate(-50%, -50%)'
    this.guide.style.filter = 'drop-shadow(0px 0px 4px rgba(0, 0, 0, 0.25))'
    this.guide.innerHTML = targetSVG
  }

  show(vec3) {
    this.target = vec3
    this.ui.appendChild(this.guide)
    this.bounds = this.ui.getBoundingClientRect()
  }

  hide() {
    if (this.target) {
      this.target = null
      this.ui.removeChild(this.guide)
    }
  }

  lateUpdate() {
    if (!this.target) return

    const vector = new THREE.Vector3().copy(this.target)
    vector.project(this.world.camera)

    const x = ((vector.x + 1) * this.bounds.width) / 2
    const y = ((-vector.y + 1) * this.bounds.height) / 2

    // Point behind camera => hide
    if (vector.z > 1) {
      this.guide.style.display = 'none'
      return
    }

    // If within -1..1 in clip space => on-screen
    if (vector.x >= -1 && vector.x <= 1 && vector.y >= -1 && vector.y <= 1) {
      // Directly place
      this.guide.style.left = `${x}px`
      this.guide.style.top = `${y}px`
      this.guide.style.display = 'block'
    } else {
      // Offscreen => pin to edge
      const centerX = this.bounds.width / 2
      const centerY = this.bounds.height / 2

      const pt = intersectLineWithRect(
        centerX,
        centerY,
        x,
        y,
        this.bounds.width,
        this.bounds.height,
        /* optional padding */ 10
      )

      if (!pt) {
        // No valid intersection => hide
        this.guide.style.display = 'none'
        return
      }

      this.guide.style.left = `${pt.x}px`
      this.guide.style.top = `${pt.y}px`
      this.guide.style.display = 'block'
    }
  }

  destroy() {
    this.hide()
  }
}

const targetSVG = `
<svg
  xmlns='http://www.w3.org/2000/svg'
  width='24'
  height='24'
  viewBox='0 0 24 24'
  fill='none'
  stroke='currentColor'
  stroke-width='2'
  stroke-linecap='round'
  stroke-linejoin='round'
  class='lucide lucide-crosshair'
>
  <circle cx='12' cy='12' r='10' />
  <line x1='22' x2='18' y1='12' y2='12' />
  <line x1='6' x2='2' y1='12' y2='12' />
  <line x1='12' x2='12' y1='6' y2='2' />
  <line x1='12' x2='12' y1='22' y2='18' />
</svg>
`

/**
 * Intersect a line from (cx, cy) to (x, y) with the 2D rectangle
 * [0, width] x [0, height].
 *
 * Returns { x, y } of the intersection on the rectangle's boundary.
 * If the line is strictly outside or parallel in that direction,
 * we won't get a valid intersection => returns null.
 */

function intersectLineWithRect(cx, cy, x, y, width, height, padding = 0) {
  // Parametric form: P(t) = center + t*(dx, dy)
  const dx = x - cx
  const dy = y - cy

  // If (x, y) == (cx, cy), there's no direction
  if (dx === 0 && dy === 0) return { x: cx, y: cy }

  let tMin = Number.POSITIVE_INFINITY

  // For each boundary, solve for t where we intersect
  // 1) Left boundary: X = 0
  if (dx !== 0) {
    const t = (0 - cx) / dx
    if (t > 0) {
      const iy = cy + t * dy
      // Must be within [0, height]
      if (iy >= 0 && iy <= height) {
        tMin = Math.min(tMin, t)
      }
    }
  }
  // 2) Right boundary: X = width
  if (dx !== 0) {
    const t = (width - cx) / dx
    if (t > 0) {
      const iy = cy + t * dy
      if (iy >= 0 && iy <= height) {
        tMin = Math.min(tMin, t)
      }
    }
  }
  // 3) Top boundary: Y = 0
  if (dy !== 0) {
    const t = (0 - cy) / dy
    if (t > 0) {
      const ix = cx + t * dx
      if (ix >= 0 && ix <= width) {
        tMin = Math.min(tMin, t)
      }
    }
  }
  // 4) Bottom boundary: Y = height
  if (dy !== 0) {
    const t = (height - cy) / dy
    if (t > 0) {
      const ix = cx + t * dx
      if (ix >= 0 && ix <= width) {
        tMin = Math.min(tMin, t)
      }
    }
  }

  if (tMin === Number.POSITIVE_INFINITY) {
    // Could not find intersection in front of center
    return null
  }

  // Intersection point
  const ix = cx + tMin * dx
  const iy = cy + tMin * dy

  // Optionally clamp to [padding, width - padding], etc.
  const clampedX = Math.min(Math.max(ix, padding), width - padding)
  const clampedY = Math.min(Math.max(iy, padding), height - padding)

  return { x: clampedX, y: clampedY }
}

import { isBoolean } from 'lodash-es'
import { ControlPriorities } from '../extras/ControlPriorities'
import { System } from './System'
import { thickness } from 'three/src/nodes/TSL.js'

const appPanes = ['app', 'script', 'nodes', 'meta']

export class ClientUI extends System {
  constructor(world) {
    super(world)
    this.state = {
      visible: true,
      active: false,
      app: null,
      pane: null,
      reticleSuppressors: 0,
    }
    this.lastAppPane = 'app'
    this.control = null
  }

  start() {
    this.control = this.world.controls.bind({ priority: ControlPriorities.CORE_UI })
  }

  update() {
    if (this.control.escape.pressed) {
      if (this.state.pane) {
        this.state.pane = null
        this.broadcast()
      } else if (this.state.app) {
        this.state.app = null
        this.broadcast()
      }
    }
    if (
      this.control.keyZ.pressed &&
      !this.control.metaLeft.down &&
      !this.control.controlLeft.down &&
      !this.control.shiftLeft.down
    ) {
      this.state.visible = !this.state.visible
      this.broadcast()
    }
    if (this.control.pointer.locked && this.state.active) {
      this.state.active = false
      this.broadcast()
    }
    if (!this.control.pointer.locked && !this.state.active) {
      this.state.active = true
      this.broadcast()
    }
  }

  togglePane(pane) {
    if (pane === null || this.state.pane === pane) {
      this.state.pane = null
    } else {
      // if (appPanes.includes(this.state.pane) && !appPanes.includes(pane)) {
      //   this.state.app = null
      // }
      this.state.pane = pane
      if (appPanes.includes(pane)) {
        this.lastAppPane = pane
      }
    }
    this.broadcast()
  }

  toggleVisible(value) {
    value = isBoolean(value) ? value : !this.state.visible
    if (this.state.visible === value) return
    this.state.visible = value
    this.broadcast()
  }

  setApp(app) {
    this.state.app = app
    this.state.pane = app ? this.lastAppPane : null
    this.broadcast()
  }

  suppressReticle() {
    this.state.reticleSuppressors++
    let released
    this.broadcast()
    return () => {
      if (released) return
      this.state.reticleSuppressors--
      this.broadcast()
      released = true
    }
  }

  confirm(options) {
    const promise = new Promise(resolve => {
      options.confirm = () => {
        this.world.emit('confirm', null)
        resolve(true)
      }
      options.cancel = () => {
        this.world.emit('confirm', null)
        resolve(false)
      }
    })
    this.world.emit('confirm', options)
    return promise
  }

  broadcast() {
    this.world.emit('ui', { ...this.state })
  }

  destroy() {
    this.control?.release()
    this.control = null
  }
}

import { System } from './System'
import Controller from '@cartridge/controller'
import { constants } from 'starknet'

/**
 * Client Web3 System
 *
 * - Runs on the client
 * - Provides Cartridge Controller integration for StarkNet wallet functionality
 * - Exposes wallet methods through world.web3 API
 *
 */
export class ClientWeb3 extends System {
  constructor(world) {
    super(world)
    this.controller = null
    this.account = null
    this.isConnected = false
    this.address = null
    this.networkId = null
    this.listeners = new Map()
  }

  init({
    policies = null,
    chains = null,
    defaultChainId = constants.StarknetChainId.SN_SEPOLIA,
    keychainUrl = 'https://x.cartridge.gg',
  } = {}) {
    const config = {
      keychainUrl,
      defaultChainId,
    }

    // Add policies if provided
    if (policies) {
      config.policies = policies
    }

    // Add custom chain configuration if provided
    if (chains) {
      config.chains = chains
    } else {
      // Default chains
      config.chains = [
        { rpcUrl: 'https://api.cartridge.gg/x/starknet/sepolia' },
        { rpcUrl: 'https://api.cartridge.gg/x/starknet/mainnet' },
      ]
    }

    // Initialize controller
    this.controller = new Controller(config)

    // Add web3 API to world
    this.world.web3 = {
      // Connection methods
      connect: this.connect,
      disconnect: this.disconnect,
      isConnected: () => this.isConnected,

      // Account info
      getAddress: () => this.address,
      getNetworkId: () => this.networkId,
      getAccount: () => this.account,

      // Transaction methods
      execute: this.execute,

      // Event listeners
      on: this.on,
      off: this.off,

      // Direct controller access for advanced usage
      getController: () => this.controller,
    }

    console.log('[ClientWeb3] Cartridge Controller initialized')
  }

  connect = async () => {
    try {
      console.log('[ClientWeb3] Connecting to Cartridge Controller...')

      this.account = await this.controller.connect()

      if (this.account) {
        this.isConnected = true
        this.address = this.account.address
        this.networkId = await this.account.getChainId()

        console.log('[ClientWeb3] Connected:', {
          address: this.address,
          chainId: this.networkId,
        })

        this.emit('connected', {
          address: this.address,
          chainId: this.networkId,
        })

        return {
          address: this.address,
          chainId: this.networkId,
          account: this.account,
        }
      }

      throw new Error('Failed to connect wallet')
    } catch (error) {
      console.error('[ClientWeb3] Connection failed:', error)
      this.emit('error', { type: 'connection', error })
      throw error
    }
  }

  disconnect = async () => {
    try {
      console.log('[ClientWeb3] Disconnecting...')

      if (this.controller && this.controller.disconnect) {
        await this.controller.disconnect()
      }

      this.account = null
      this.isConnected = false
      this.address = null
      this.networkId = null

      this.emit('disconnected')

      console.log('[ClientWeb3] Disconnected')
    } catch (error) {
      console.error('[ClientWeb3] Disconnect failed:', error)
      this.emit('error', { type: 'disconnect', error })
      throw error
    }
  }

  execute = async (calls, options = {}) => {
    if (!this.isConnected || !this.account) {
      throw new Error('Wallet not connected. Call world.web3.connect() first.')
    }

    try {
      console.log('[ClientWeb3] Executing transaction...', calls)

      const result = await this.account.execute(calls, options)

      console.log('[ClientWeb3] Transaction executed:', result)
      this.emit('transaction', { result })

      return result
    } catch (error) {
      console.error('[ClientWeb3] Transaction failed:', error)
      this.emit('error', { type: 'transaction', error })
      throw error
    }
  }

  on = (event, callback) => {
    if (!this.listeners.has(event)) {
      this.listeners.set(event, new Set())
    }
    this.listeners.get(event).add(callback)
  }

  off = (event, callback) => {
    if (this.listeners.has(event)) {
      this.listeners.get(event).delete(callback)
    }
  }

  emit = (event, data) => {
    if (this.listeners.has(event)) {
      this.listeners.get(event).forEach(callback => {
        try {
          callback(data)
        } catch (error) {
          console.error(`[ClientWeb3] Event listener error (${event}):`, error)
        }
      })
    }
  }

  destroy() {
    this.disconnect()
    this.listeners.clear()
    if (this.world.web3) {
      delete this.world.web3
    }
    console.log('[ClientWeb3] Destroyed')
  }
}

import { System } from './System'

export class Collections extends System {
  constructor(world) {
    super(world)
    this.collections = []
  }

  init({ collections }) {
    if (collections) {
      this.deserialize(collections)
    }
  }

  get(id) {
    return this.collections.find(coll => coll.id === id)
  }

  deserialize(data) {
    this.collections = data
  }

  serialize() {
    return this.collections
  }

  destroy() {
    this.collections = []
  }
}

/**
 * Enhanced Camera System
 *
 * A game-engine-style camera management system that provides:
 * - Multiple camera types (Follow, Orbit, FirstPerson, Free, Cinematic)
 * - Smooth transitions and blending
 * - Target tracking and look-at functionality
 * - Easy camera switching and management
 * - Compatibility with both node cameras and legacy camera controls
 */

import * as THREE from '../extras/three'

const CAMERA_TYPES = {
  FOLLOW: 'follow',
  ORBIT: 'orbit',
  FIRST_PERSON: 'firstPerson',
  FREE: 'free',
  CINEMATIC: 'cinematic',
}

const TRANSITION_TYPES = {
  CUT: 'cut',
  SMOOTH: 'smooth',
  BLEND: 'blend',
}

export class EnhancedCameraSystem {
  constructor(world) {
    this.world = world
    this.cameras = new Map()
    this.activeCamera = null
    this.previousCamera = null
    this.transitionProgress = 0
    this.transitionDuration = 0
    this.transitionType = TRANSITION_TYPES.CUT

    // Default camera settings
    this.defaultSettings = {
      fov: 73,
      near: 0.2,
      far: 1200,
      position: new THREE.Vector3(0, 1.6, 0),
      rotation: new THREE.Euler(0, 0, 0, 'YXZ'),
    }

    // Camera state for smooth transitions
    this.currentCameraState = {
      position: new THREE.Vector3(),
      rotation: new THREE.Euler(),
      fov: 73,
    }

    this.targetCameraState = {
      position: new THREE.Vector3(),
      rotation: new THREE.Euler(),
      fov: 73,
    }
  }

  /**
   * Create a new camera with enhanced game-engine-style settings
   */
  createCamera(name, type = CAMERA_TYPES.FOLLOW, options = {}) {
    const camera = {
      name,
      type,
      active: false,
      settings: { ...this.defaultSettings, ...options },

      // Game engine style properties
      target: options.target || null,
      followDistance: options.followDistance || 5,
      followHeight: options.followHeight || 2,
      lookAtTarget: options.lookAtTarget !== false,
      smoothFollow: options.smoothFollow !== false,
      collisionDetection: options.collisionDetection !== false,

      // Camera controls
      enableInput: options.enableInput !== false,
      enableZoom: options.enableZoom !== false,
      enableRotation: options.enableRotation !== false,

      // Movement settings
      moveSpeed: options.moveSpeed || 10,
      lookSpeed: options.lookSpeed || 2,
      zoomSpeed: options.zoomSpeed || 2,

      // Limits
      minDistance: options.minDistance || 1,
      maxDistance: options.maxDistance || 50,
      minPitch: options.minPitch || -89,
      maxPitch: options.maxPitch || 89,

      // Advanced settings
      damping: options.damping || 0.1,
      springStrength: options.springStrength || 0.1,
      targetOffset: options.targetOffset || new THREE.Vector3(0, 1, 0),
    }

    // Create the actual Three.js camera
    camera.camera = new THREE.PerspectiveCamera(
      camera.settings.fov,
      camera.settings.aspect || 1,
      camera.settings.near,
      camera.settings.far
    )

    // Set initial position
    camera.camera.position.copy(camera.settings.position)
    camera.camera.rotation.copy(camera.settings.rotation)

    // Type-specific setup
    this.setupCameraByType(camera)

    this.cameras.set(name, camera)
    return camera
  }

  setupCameraByType(camera) {
    switch (camera.type) {
      case CAMERA_TYPES.FOLLOW:
        this.setupFollowCamera(camera)
        break
      case CAMERA_TYPES.ORBIT:
        this.setupOrbitCamera(camera)
        break
      case CAMERA_TYPES.FIRST_PERSON:
        this.setupFirstPersonCamera(camera)
        break
      case CAMERA_TYPES.FREE:
        this.setupFreeCamera(camera)
        break
      case CAMERA_TYPES.CINEMATIC:
        this.setupCinematicCamera(camera)
        break
    }
  }

  setupFollowCamera(camera) {
    // Follow camera stays behind and above target
    camera.update = (delta, target) => {
      if (!target) return

      const idealPosition = new THREE.Vector3()
      const targetPosition = target.position || target

      // Calculate ideal follow position
      idealPosition.copy(targetPosition)
      idealPosition.add(camera.targetOffset)

      // Apply follow distance and height
      const direction = new THREE.Vector3(0, 0, -camera.followDistance)
      direction.applyQuaternion(target.quaternion || new THREE.Quaternion())
      idealPosition.add(direction)

      // Smooth follow
      if (camera.smoothFollow) {
        camera.camera.position.lerp(idealPosition, delta * camera.damping * 10)
      } else {
        camera.camera.position.copy(idealPosition)
      }

      // Look at target
      if (camera.lookAtTarget) {
        const lookAtPos = new THREE.Vector3().copy(targetPosition)
        lookAtPos.add(camera.targetOffset)
        camera.camera.lookAt(lookAtPos)
      }
    }
  }

  setupOrbitCamera(camera) {
    // Orbit camera rotates around target
    camera.orbitAngle = 0
    camera.orbitRadius = camera.followDistance
    camera.orbitHeight = camera.followHeight

    camera.update = (delta, target) => {
      if (!target) return

      const targetPosition = target.position || target

      // Calculate orbit position
      const x = Math.cos(camera.orbitAngle) * camera.orbitRadius
      const z = Math.sin(camera.orbitAngle) * camera.orbitRadius

      camera.camera.position.set(targetPosition.x + x, targetPosition.y + camera.orbitHeight, targetPosition.z + z)

      // Look at target
      camera.camera.lookAt(targetPosition)
    }
  }

  setupFirstPersonCamera(camera) {
    // First person camera attached to target
    camera.update = (delta, target) => {
      if (!target) return

      const targetPosition = target.position || target
      const targetRotation = target.quaternion || new THREE.Quaternion()

      // Position camera at target's eye level
      camera.camera.position.copy(targetPosition)
      camera.camera.position.y += camera.targetOffset.y

      // Copy target rotation
      camera.camera.quaternion.copy(targetRotation)
    }
  }

  setupFreeCamera(camera) {
    // Free camera with full movement control
    camera.velocity = new THREE.Vector3()
    camera.angularVelocity = new THREE.Vector3()

    camera.update = (delta, input) => {
      // Apply input-based movement
      if (input && camera.enableInput) {
        const moveVector = new THREE.Vector3()

        if (input.forward) moveVector.z -= 1
        if (input.backward) moveVector.z += 1
        if (input.left) moveVector.x -= 1
        if (input.right) moveVector.x += 1
        if (input.up) moveVector.y += 1
        if (input.down) moveVector.y -= 1

        moveVector.normalize()
        moveVector.multiplyScalar(camera.moveSpeed * delta)

        // Apply movement relative to camera rotation
        moveVector.applyQuaternion(camera.camera.quaternion)
        camera.velocity.add(moveVector)
      }

      // Apply velocity with damping
      camera.velocity.multiplyScalar(1 - camera.damping)
      camera.camera.position.add(camera.velocity)

      // Apply rotation
      if (input && camera.enableRotation) {
        camera.camera.rotation.y -= input.lookX * camera.lookSpeed * delta
        camera.camera.rotation.x -= input.lookY * camera.lookSpeed * delta

        // Clamp pitch
        camera.camera.rotation.x = Math.max(
          (camera.minPitch * Math.PI) / 180,
          Math.min((camera.maxPitch * Math.PI) / 180, camera.camera.rotation.x)
        )
      }
    }
  }

  setupCinematicCamera(camera) {
    // Cinematic camera with predefined paths and automated movement
    camera.path = options.path || []
    camera.pathIndex = 0
    camera.pathProgress = 0

    camera.update = delta => {
      if (camera.path.length === 0) return

      // Move along path
      camera.pathProgress += delta * camera.moveSpeed

      if (camera.pathProgress >= 1) {
        camera.pathProgress = 0
        camera.pathIndex = (camera.pathIndex + 1) % camera.path.length
      }

      // Interpolate position along path
      const currentPoint = camera.path[camera.pathIndex]
      const nextPoint = camera.path[(camera.pathIndex + 1) % camera.path.length]

      camera.camera.position.lerpVectors(currentPoint, nextPoint, camera.pathProgress)

      // Look at next point or target
      if (camera.target) {
        camera.camera.lookAt(camera.target.position || camera.target)
      } else {
        camera.camera.lookAt(nextPoint)
      }
    }
  }

  /**
   * Switch to a different camera with smooth transition
   */
  switchCamera(name, transitionType = TRANSITION_TYPES.SMOOTH, duration = 1.0) {
    const camera = this.cameras.get(name)
    if (!camera) {
      console.warn(`Camera '${name}' not found`)
      return
    }

    this.previousCamera = this.activeCamera
    this.activeCamera = camera
    this.transitionType = transitionType
    this.transitionDuration = duration
    this.transitionProgress = 0

    // Set target state for smooth transition
    this.targetCameraState.position.copy(camera.camera.position)
    this.targetCameraState.rotation.copy(camera.camera.rotation)
    this.targetCameraState.fov = camera.settings.fov

    if (transitionType === TRANSITION_TYPES.CUT) {
      // Immediate switch
      this.currentCameraState.position.copy(this.targetCameraState.position)
      this.currentCameraState.rotation.copy(this.targetCameraState.rotation)
      this.currentCameraState.fov = this.targetCameraState.fov
      this.transitionProgress = 1
    }

    // Deactivate previous camera
    if (this.previousCamera) {
      this.previousCamera.active = false
    }

    // Activate new camera
    camera.active = true

    console.log(`Switched to camera: ${name} (${camera.type})`)
  }

  /**
   * Update camera system
   */
  update(delta) {
    if (!this.activeCamera) return

    // Update transition
    if (this.transitionProgress < 1) {
      this.transitionProgress += delta / this.transitionDuration
      this.transitionProgress = Math.min(1, this.transitionProgress)

      // Smooth interpolation
      const t = this.smoothStep(this.transitionProgress)

      this.currentCameraState.position.lerp(
        this.previousCamera ? this.previousCamera.camera.position : this.currentCameraState.position,
        this.targetCameraState.position,
        t
      )

      this.currentCameraState.rotation.x = THREE.MathUtils.lerp(
        this.previousCamera ? this.previousCamera.camera.rotation.x : this.currentCameraState.rotation.x,
        this.targetCameraState.rotation.x,
        t
      )

      this.currentCameraState.rotation.y = THREE.MathUtils.lerp(
        this.previousCamera ? this.previousCamera.camera.rotation.y : this.currentCameraState.rotation.y,
        this.targetCameraState.rotation.y,
        t
      )

      this.currentCameraState.fov = THREE.MathUtils.lerp(
        this.previousCamera ? this.previousCamera.settings.fov : this.currentCameraState.fov,
        this.targetCameraState.fov,
        t
      )
    }

    // Update active camera
    const target = this.getTargetForCamera(this.activeCamera)
    const input = this.getInputForCamera(this.activeCamera)

    this.activeCamera.update(delta, target, input)

    // Apply collision detection if enabled
    if (this.activeCamera.collisionDetection) {
      this.applyCollisionDetection(this.activeCamera)
    }

    // Update world camera
    this.updateWorldCamera()
  }

  getTargetForCamera(camera) {
    // Get appropriate target based on camera type
    if (camera.type === CAMERA_TYPES.FOLLOW || camera.type === CAMERA_TYPES.FIRST_PERSON) {
      return this.world.rig || this.world.camera
    }
    return camera.target
  }

  getInputForCamera(camera) {
    // Get input state for camera control
    if (!camera.enableInput || !this.world.controls) return null

    const control = this.world.controls.getActiveControl()
    if (!control) return null

    return {
      forward: control.keyW?.down,
      backward: control.keyS?.down,
      left: control.keyA?.down,
      right: control.keyD?.down,
      up: control.keySpace?.down,
      down: control.keyShift?.down,
      lookX: control.pointer?.delta.x || 0,
      lookY: control.pointer?.delta.y || 0,
    }
  }

  applyCollisionDetection(camera) {
    // Simple collision detection to prevent camera from going through walls
    if (!this.world.physics) return

    // Implementation depends on physics system availability
    // This is a placeholder for collision detection logic
  }

  updateWorldCamera() {
    // Update the world's main camera with active camera state
    if (this.world.camera) {
      this.world.camera.position.copy(this.activeCamera.camera.position)
      this.world.camera.quaternion.copy(this.activeCamera.camera.quaternion)
      this.world.camera.fov = this.activeCamera.settings.fov
    }
  }

  smoothStep(t) {
    // Smooth interpolation function
    return t * t * (3 - 2 * t)
  }

  /**
   * Get camera by name
   */
  getCamera(name) {
    return this.cameras.get(name)
  }

  /**
   * Get active camera
   */
  getActiveCamera() {
    return this.activeCamera
  }

  /**
   * List all cameras
   */
  listCameras() {
    return Array.from(this.cameras.keys())
  }

  /**
   * Remove camera
   */
  removeCamera(name) {
    const camera = this.cameras.get(name)
    if (camera) {
      if (camera.active) {
        this.activeCamera = null
      }
      this.cameras.delete(name)
    }
  }

  /**
   * Camera presets for common game scenarios
   */
  createPresetCameras() {
    const cameras = {}

    // Third Person Follow
    cameras.thirdPerson = this.createCamera('thirdPerson', CAMERA_TYPES.FOLLOW, {
      followDistance: 5,
      followHeight: 2,
      lookAtTarget: true,
      smoothFollow: true,
      damping: 0.1,
    })

    // First Person
    cameras.firstPerson = this.createCamera('firstPerson', CAMERA_TYPES.FIRST_PERSON, {
      targetOffset: new THREE.Vector3(0, 1.6, 0),
    })

    // Orbit Camera
    cameras.orbit = this.createCamera('orbit', CAMERA_TYPES.ORBIT, {
      orbitRadius: 10,
      orbitHeight: 5,
      enableInput: true,
      enableRotation: true,
    })

    // Free Camera
    cameras.free = this.createCamera('free', CAMERA_TYPES.FREE, {
      enableInput: true,
      enableRotation: true,
      enableZoom: true,
      moveSpeed: 15,
      lookSpeed: 2,
    })

    // Cinematic Camera
    cameras.cinematic = this.createCamera('cinematic', CAMERA_TYPES.CINEMATIC, {
      moveSpeed: 0.5,
      lookAtTarget: true,
    })

    return cameras
  }
}

