import { AccessToken, TrackSource } from 'livekit-server-sdk'

import { System } from './System'
import { uuid } from '../utils'

const levels = ['disabled', 'spatial', 'global']
const levelPriorities = {
  disabled: 1,
  spatial: 2,
  global: 3,
}

export class ServerLiveKit extends System {
  constructor(world) {
    super(world)
    this.roomId = uuid()
    this.wsUrl = process.env.LIVEKIT_WS_URL
    this.apiKey = process.env.LIVEKIT_API_KEY
    this.apiSecret = process.env.LIVEKIT_API_SECRET
    this.enabled = this.wsUrl && this.apiKey && this.apiSecret
    this.modifiers = {} // [playerId] => Set({ level })
    this.levels = {} // [playerId] => level (disabled, spatial, global)
    this.muted = new Set()
  }

  async serialize(playerId) {
    if (!this.enabled) return null
    const data = {}
    data.wsUrl = this.wsUrl
    data.levels = this.levels
    data.muted = this.muted
    // generate voice access token for the player
    const at = new AccessToken(this.apiKey, this.apiSecret, {
      identity: playerId,
    })
    const videoGrant = {
      room: this.roomId,
      roomJoin: true,
      canSubscribe: true,
      canPublish: true,
      canPublishSources: [TrackSource.MICROPHONE, TrackSource.SCREEN_SHARE, TrackSource.SCREEN_SHARE_AUDIO],
      canUpdateOwnMetadata: true,
    }
    at.addGrant(videoGrant)
    data.token = await at.toJwt()
    return data
  }

  setMuted(playerId, muted) {
    if (muted && !this.muted.has(playerId)) {
      this.muted.add(playerId)
      this.world.network.send('mute', { playerId, muted })
      return
    }
    if (!muted && this.muted.has(playerId)) {
      this.muted.delete(playerId)
      this.world.network.send('mute', { playerId, muted })
      return
    }
  }

  addModifier(playerId, level) {
    if (!levels.includes(level)) return console.error(`[livekit] invalid level: ${level}`)
    let modifiers = this.modifiers[playerId]
    if (!modifiers) {
      modifiers = new Set()
      this.modifiers[playerId] = modifiers
    }
    const mod = { playerId, level }
    modifiers.add(mod)
    this.checkLevel(playerId)
    return mod
  }

  updateModifier(mod, level) {
    if (!levels.includes(level)) return console.error(`[livekit] invalid level: ${level}`)
    const playerId = mod.playerId
    const modifiers = this.modifiers[playerId]
    if (!modifiers) return
    if (!modifiers.has(mod)) return console.error('updateModifier: mod not found')
    mod.level = level
    this.checkLevel(playerId)
    return mod
  }

  removeModifier(mod) {
    const playerId = mod.playerId
    const modifiers = this.modifiers[playerId]
    if (!modifiers) return
    modifiers.delete(mod)
    this.checkLevel(playerId)
    return null
  }

  clearModifiers(playerId) {
    delete this.modifiers[playerId]
    this.checkLevel(playerId)
  }

  checkLevel(playerId) {
    const modifiers = this.modifiers[playerId]
    let level = null
    if (modifiers) {
      for (const mod of modifiers) {
        const currPriority = levelPriorities[level] || 0
        const modPriority = levelPriorities[mod.level]
        if (modPriority > currPriority) {
          level = mod.level
        }
      }
    }
    if (this.levels[playerId] === level) {
      return // no change
    }
    this.levels[playerId] = level
    this.world.network.send('liveKitLevel', { playerId, level })
  }
}

import fs from 'fs-extra'
import path from 'path'
import { RGBELoader } from 'three/examples/jsm/loaders/RGBELoader.js'
// import { GLTFLoader } from 'three/examples/jsm/loaders/GLTFLoader.js'
import { GLTFLoader } from '../libs/gltfloader/GLTFLoader.js'
// import { VRMLoaderPlugin } from '@pixiv/three-vrm'

import { System } from './System'
import { createVRMFactory } from '../extras/createVRMFactory'
import { glbToNodes } from '../extras/glbToNodes'
import { createNode } from '../extras/createNode'
import { createEmoteFactory } from '../extras/createEmoteFactory'

/**
 * Server Loader System
 *
 * - Runs on the server
 * - Basic file loader for many different formats, cached.
 *
 */
export class ServerLoader extends System {
  constructor(world) {
    super(world)
    this.promises = new Map()
    this.results = new Map()
    this.rgbeLoader = new RGBELoader()
    this.gltfLoader = new GLTFLoader()
    this.preloadItems = []
    // this.gltfLoader.register(parser => new VRMLoaderPlugin(parser))

    // mock globals to allow gltf loader to work in nodejs
    globalThis.self = { URL }
    globalThis.window = {}
    globalThis.document = {
      createElementNS: () => ({ style: {} }),
    }
  }

  start() {
    // ...
  }

  has(type, url) {
    const key = `${type}/${url}`
    return this.promises.has(key)
  }

  get(type, url) {
    const key = `${type}/${url}`
    return this.results.get(key)
  }

  preload(type, url) {
    this.preloadItems.push({ type, url })
  }

  execPreload() {
    const promises = this.preloadItems.map(item => this.load(item.type, item.url))
    this.preloader = Promise.allSettled(promises).then(() => {
      this.preloader = null
    })
  }

  async fetchArrayBuffer(url) {
    const isRemote = url.startsWith('http://') || url.startsWith('https://')
    if (isRemote) {
      const response = await fetch(url)
      const arrayBuffer = await response.arrayBuffer()
      return arrayBuffer
    } else {
      const buffer = await fs.readFile(url)
      const arrayBuffer = buffer.buffer.slice(buffer.byteOffset, buffer.byteOffset + buffer.byteLength)
      return arrayBuffer
    }
  }

  async fetchText(url) {
    const isRemote = url.startsWith('http://') || url.startsWith('https://')
    if (isRemote) {
      const response = await fetch(url)
      const text = await response.text()
      return text
    } else {
      const text = await fs.readFile(url, { encoding: 'utf8' })
      return text
    }
  }

  load(type, url) {
    const key = `${type}/${url}`
    if (this.promises.has(key)) {
      return this.promises.get(key)
    }
    url = this.world.resolveURL(url, true)

    let promise
    if (type === 'hdr') {
      // promise = this.rgbeLoader.loadAsync(url).then(texture => {
      //   return texture
      // })
    }
    if (type === 'image') {
      // ...
    }
    if (type === 'texture') {
      // ...
    }
    if (type === 'model') {
      promise = new Promise(async (resolve, reject) => {
        try {
          const arrayBuffer = await this.fetchArrayBuffer(url)
          this.gltfLoader.parse(arrayBuffer, '', glb => {
            const node = glbToNodes(glb, this.world)
            const model = {
              toNodes() {
                return node.clone(true)
              },
            }
            this.results.set(key, model)
            resolve(model)
          })
        } catch (err) {
          reject(err)
        }
      })
    }
    if (type === 'emote') {
      promise = new Promise(async (resolve, reject) => {
        try {
          const arrayBuffer = await this.fetchArrayBuffer(url)
          this.gltfLoader.parse(arrayBuffer, '', glb => {
            const factory = createEmoteFactory(glb, url)
            const emote = {
              toClip(options) {
                return factory.toClip(options)
              },
            }
            this.results.set(key, emote)
            resolve(emote)
          })
        } catch (err) {
          reject(err)
        }
      })
    }
    if (type === 'avatar') {
      promise = new Promise(async (resolve, reject) => {
        try {
          // NOTE: we can't load vrms on the server yet but we don't need 'em anyway
          let node
          const glb = {
            toNodes: () => {
              if (!node) {
                node = createNode('group')
                const node2 = createNode('avatar', { id: 'avatar', factory: null })
                node.add(node2)
              }
              return node.clone(true)
            },
          }
          this.results.set(key, glb)
          resolve(glb)
        } catch (err) {
          reject(err)
        }
      })
    }
    if (type === 'script') {
      promise = new Promise(async (resolve, reject) => {
        try {
          const code = await this.fetchText(url)
          const script = this.world.scripts.evaluate(code)
          this.results.set(key, script)
          resolve(script)
        } catch (err) {
          reject(err)
        }
      })
    }
    if (type === 'audio') {
      promise = new Promise(async (resolve, reject) => {
        reject(null)
      })
    }
    this.promises.set(key, promise)
    return promise
  }

  destroy() {
    this.promises.clear()
    this.results.clear()
    this.preloadItems = []
  }
}

import { System } from './System'
import os from 'os'

export class ServerMonitor extends System {
  constructor(world) {
    super(world)
  }

  async getStats() {
    const memUsage = process.memoryUsage()
    const startCPU = process.cpuUsage()
    await new Promise(resolve => setTimeout(resolve, 100))
    const endCPU = process.cpuUsage(startCPU)
    const cpuPercent = (endCPU.user + endCPU.system) / 1000 / 100
    return {
      maxMemory: Math.round(os.totalmem() / 1024 / 1024),
      currentMemory: Math.round(memUsage.rss / 1024 / 1024),
      maxCPU: os.cpus().length * 100,
      currentCPU: cpuPercent,
    }
  }
}

